window.__X_NEWS__ = {"updated_at": "2026-10-22 05:08 Asia/Shanghai", "updated_at_iso": "2026-10-21T21:08:03.000Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112905930044317939", "domain": "科技", "title_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Nobel laureate David Baker sees a new era: designing proteins from scratch, not just discovering nature's own. This tool makes it faster and more reliable than ever.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "NVIDIA and the University of Washington's Institute for Protein Design released RFD4-Proteina, an open model that generates proteins and biomolecules up to 13 times faster than prior tools like RFdiffusion3. Born from a year-long collaboration between Baker Lab and NVIDIA’s GenAIR team, it unifies amino acids, sugars, DNA, and RNA in one space, enabling designs for drug binders and enzymes—including one that helps synthesize the HIV drug lenacapavir. Fully open-source on GitHub and Hugging Face, with free GPU access for two weeks, it promises to boost fields from drug discovery to industrial enzymes and protein design competitions.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T19:42:52.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。Samuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持。\n\nOpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。\n\n去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。\n\nSamuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国国土安全部令联邦机构清除 DeepSeek AI 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。 DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nThe U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.\n\nUnder a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services.\n\nThe order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "body_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。\n\n根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。\n\n该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112891431543275870", "domain": "科技", "title_en": "NVIDIA Unveils DSX POD for Rapid AI Factory Deployment", "title_zh": "英伟达 DSX POD：两周内搭起 AI 工厂", "hook_en": "Imagine turning months of AI setup into just 14 days. NVIDIA's new DSX POD makes that real, arriving as a ready-to-run shipping container packed with cutting-edge hardware.", "hook_zh": "过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。", "summary_en": "At GTC Berlin, CEO Jensen Huang introduced the DSX POD, a modular AI factory system pre-loaded with Vera Rubin NVL72 racks, networking, power, and liquid cooling for truck delivery. Weighing 28,500 kilograms with 100 million components, it connects to utilities on-site and goes live far faster than traditional builds, slashing scaling bottlenecks. Partners like Dell, HPE, and Lenovo will manufacture them starting early 2027, with efficiency boosts like 30 times better performance and near-zero water cooling. Huang spotlighted Nebius, a startup securing 1 GW of capacity for huge revenue potential.", "summary_zh": "在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "body_en": "NVIDIA's DSX POD Speeds AI Factories to 14 Days.\n\nImagine spinning up a massive AI factory in just two weeks instead of months. NVIDIA's new design makes that real, easing the rush for builders racing to capture billions in revenue.\n\nAt its GTC conference in Berlin, NVIDIA unveiled the DSX POD, a modular system that packages Vera Rubin AI factories into shippable containers built and tested by partners like Dell, HPE, and Lenovo. These units cut deployment time to as little as 14 days once power, cooling, and networking are ready, addressing delays that cost billions in lost revenue for 1-gigawatt facilities.\n\nThe design also boosts efficiency with closed-loop liquid cooling that slashes water use by up to 100 percent and power needs by 30 percent, helping operators generate output while permanent data centers are built. Partners will deliver the PODs worldwide starting early 2027.", "body_zh": "英伟达 DSX POD：两周内搭起 AI 工厂。\n\n过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。\n\n在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。\n\n设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "url": "https://x.com/i/trending/2112891431543275870", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T20:52:40.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Brings Frontier Models to Google Cloud Platform", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "OpenAI is expanding beyond Microsoft, teaming up with Google Cloud to make its cutting-edge AI models easily available right where enterprises already run their operations.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "The new partnership lets customers access OpenAI's GPT-6 Astra, GPT-6.1 Sol, GPT-6 Luna, and Codex workflows directly through Google Cloud's Model Garden and Marketplace. Enterprises can use their existing Google Cloud commitments to purchase these models, simplifying how they build complex AI agents at scale. Google Cloud now offers Gemini, Claude, and GPT models alongside over 200 others on one platform, following OpenAI's recent moves to AWS after ending its Microsoft exclusivity. This deal highlights growing customer choice across major cloud providers for top AI technology.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:43:33.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI收购Orchestra Bio以加快药物开发", "hook_en": "OpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.", "hook_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。", "summary_en": "On October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk. Founder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "summary_zh": "2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。 创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nOpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.\n\nOn October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk.\n\nFounder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "body_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。\n\n2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。\n\n创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T12:34:03.000Z"}, {"id": "2112891431501390231", "domain": "科技", "title_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents", "title_zh": "NVIDIA推出OpenShell以保护企业AI代理", "hook_en": "At GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.", "hook_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。", "summary_en": "The OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0. Over 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "summary_zh": "OpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。 Anthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "body_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents.\n\nAt GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.\n\nThe OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0.\n\nOver 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "body_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。\n\nOpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。\n\nAnthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "url": "https://x.com/i/trending/2112891431501390231", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:02:53.000Z"}, {"id": "2112575527206969617", "domain": "科技", "title_en": "Google's Gemini 4 Argon Processes 25 Trillion Tokens in First 72 Hours", "title_zh": "谷歌的Gemini 4 Argon在前72小时内处理了25万亿个代币", "hook_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.", "hook_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。", "summary_en": "Launched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window. It leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "summary_zh": "Argon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。 Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "body_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.\n\nLaunched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window.\n\nIt leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "body_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。\n\nArgon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。\n\n它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "url": "https://x.com/i/trending/2112575527206969617", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:22:34.000Z"}, {"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112299444591116780", "domain": "科技", "title_en": "Amazon and Google Launch PyTorch Tools for Custom AI Chips", "title_zh": "亚马逊和谷歌推出用于定制AI芯片的PyTorch工具", "hook_en": "Developers can now run PyTorch code on Amazon and Google's AI chips with just a single tweak, easing the switch from Nvidia hardware.", "hook_zh": "开发人员现在可以在亚马逊和谷歌的人工智能芯片上运行PyTorch代码，只需一次调整，就可以轻松切换Nvidia硬件。", "summary_en": "Amazon released TorchNeuron for its Trainium chips, while Google unveiled TorchTPU for TPUs, both open-source backends that support eager execution and fast inference on large models like Llama 3 405B. Amazon CEO Andy Jassy noted that one configuration change replaces hours of code rewriting, and Google engineer Adam Mainz celebrated the milestone. These tools, announced at the PyTorch Conference North America, boost hardware options amid PyTorch's growth, with Intel and AMD also unifying CPU support to cut developer fragmentation.", "summary_zh": "亚马逊为其Trainium芯片发布了TorchNeuron ，而谷歌则推出了用于TPU的TorchTPU ，这两个开源后端都支持Llama 3 405B等大型模型的急切执行和快速推理。亚马逊首席执行官安迪·贾西（ Andy Jassy ）指出，一次配置更改取代了数小时的代码重写，谷歌工程师亚当·美因茨（ Adam Mainz ）庆祝了这一里程碑。 在PyTorch北美大会上宣布的这些工具在PyTorch的增长中增加了硬件选择，英特尔和AMD也统一了对CPU的支持，以减少开发人员的碎片化。", "body_en": "Amazon and Google Launch PyTorch Tools for Custom AI Chips.\n\nDevelopers can now run PyTorch code on Amazon and Google's AI chips with just a single tweak, easing the switch from Nvidia hardware.\n\nAmazon released TorchNeuron for its Trainium chips, while Google unveiled TorchTPU for TPUs, both open-source backends that support eager execution and fast inference on large models like Llama 3 405B.\n\nAmazon CEO Andy Jassy noted that one configuration change replaces hours of code rewriting, and Google engineer Adam Mainz celebrated the milestone. These tools, announced at the PyTorch Conference North America, boost hardware options amid PyTorch's growth, with Intel and AMD also unifying CPU support to cut developer fragmentation.", "body_zh": "开发人员现在可以在亚马逊和谷歌的人工智能芯片上运行PyTorch代码，只需一次调整，就可以轻松切换Nvidia硬件。\n\n亚马逊为其Trainium芯片发布了TorchNeuron ，而谷歌则推出了用于TPU的TorchTPU ，这两个开源后端都支持Llama 3 405B等大型模型的急切执行和快速推理。\n\n亚马逊首席执行官安迪·贾西（ Andy Jassy ）指出，一次配置更改取代了数小时的代码重写，谷歌工程师亚当·美因茨（ Adam Mainz ）庆祝了这一里程碑。在PyTorch北美大会上宣布的这些工具在PyTorch的增长中增加了硬件选择，英特尔和AMD也统一了对CPU的支持，以减少开发人员的碎片化。", "url": "https://x.com/i/trending/2112299444591116780", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:15:44.000Z"}, {"id": "2112905935199125989", "domain": "科技", "title_en": "DeepSeek Open-Sources High-Performance AI Inference Engine Amid Google TPU Push", "title_zh": "Google TPU推送中的DeepSeek开源高性能AI推理引擎", "hook_en": "DeepSeek just released the code behind its powerhouse AI services, letting developers run massive models at blazing speeds on everyday hardware.", "hook_zh": "DeepSeek刚刚发布了其强大的人工智能服务背后的代码，允许开发人员在日常硬件上以惊人的速度运行大量模型。", "summary_en": "Chinese firm DeepSeek unveiled DeepSeek-V4.1-Flash, a large multimodal model, and open-sourced DeepInfer, its optimized inference framework under Apache-2.0 license. It supports NVIDIA Blackwell, Huawei Ascend, and delivers impressive local speeds like 410 tokens per second on four RTX PRO 6000 GPUs. Meanwhile, Google open-sourced TorchTPU at the PyTorch Conference, enabling PyTorch code to run seamlessly on Cloud TPUs. These steps boost AI accessibility despite U.S. federal restrictions on DeepSeek products over data risks.", "summary_zh": "中国公司DeepSeek推出了大型多模态模型DeepSeek-V4.1-Flash和开源的DeepInfer ，后者是Apache-2.0许可下的优化推理框架。它支持NVIDIA Blackwell、华为Ascend ，并在四个RTX PRO 6000 GPU上提供令人印象深刻的本地速度，如每秒410个令牌。同时，谷歌在PyTorch大会上开源了TorchTPU ，使PyTorch代码能够在云TPU上无缝运行。 这些步骤提高了人工智能的可访问性，尽管美国联邦政府对DeepSeek产品的数据风险进行了限制。", "body_en": "DeepSeek Open-Sources High-Performance AI Inference Engine Amid Google TPU Push.\n\nDeepSeek just released the code behind its powerhouse AI services, letting developers run massive models at blazing speeds on everyday hardware.\n\nChinese firm DeepSeek unveiled DeepSeek-V4.1-Flash, a large multimodal model, and open-sourced DeepInfer, its optimized inference framework under Apache-2.0 license. It supports NVIDIA Blackwell, Huawei Ascend, and delivers impressive local speeds like 410 tokens per second on four RTX PRO 6000 GPUs.\n\nMeanwhile, Google open-sourced TorchTPU at the PyTorch Conference, enabling PyTorch code to run seamlessly on Cloud TPUs. These steps boost AI accessibility despite U.S. federal restrictions on DeepSeek products over data risks.", "body_zh": "DeepSeek刚刚发布了其强大的人工智能服务背后的代码，允许开发人员在日常硬件上以惊人的速度运行大量模型。\n\n中国公司DeepSeek推出了大型多模态模型DeepSeek-V4.1-Flash和开源的DeepInfer ，后者是Apache-2.0许可下的优化推理框架。它支持NVIDIA Blackwell、华为Ascend ，并在四个RTX PRO 6000 GPU上提供令人印象深刻的本地速度，如每秒410个令牌。\n\n同时，谷歌在PyTorch大会上开源了TorchTPU ，使PyTorch代码能够在云TPU上无缝运行。这些步骤提高了人工智能的可访问性，尽管美国联邦政府对DeepSeek产品的数据风险进行了限制。", "url": "https://x.com/i/trending/2112905935199125989", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T18:52:21.000Z"}, {"id": "2112281282239664552", "domain": "科技", "title_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer", "title_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟", "hook_en": "NVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.", "hook_zh": "英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。", "summary_en": "On Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science. CEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "summary_zh": "在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。CEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "body_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer.\n\nNVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.\n\nOn Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science.\n\nCEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "body_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟。\n\n英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。\n\n在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。\n\nCEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "url": "https://x.com/i/trending/2112281282239664552", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-19T20:43:59.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 将股份拨入公益基金", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 将股份拨入公益基金。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112933585816781110", "domain": "商业", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z"}, {"id": "2112908300035776814", "domain": "商业", "title_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth", "title_zh": "美光与英伟达贡献标普 500 盈利增长的 36%", "hook_en": "Two tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.", "hook_zh": "两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。", "summary_en": "For Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter. Without the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "summary_zh": "预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。", "body_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth.\n\nTwo tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.\n\nFor Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter.\n\nWithout the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "body_zh": "美光与英伟达贡献标普 500 盈利增长的 36%。\n\n两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。\n\n预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。\n\n若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。", "url": "https://x.com/i/trending/2112908300035776814", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:44:49.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112974495564865717", "domain": "商业", "title_en": "SpaceX Shares Jump 15% on Earnings Beat and Raised Price Targets", "title_zh": "SpaceX第三季度利润和人工智能热潮创纪录，股价飙升15%", "hook_en": "SpaceX just crushed earnings expectations, sending shares soaring over 15% to $163 amid heavy trading. Wall Street analysts piled on with big price target hikes, spotlighting explosive growth in its Super Intelligence segment.", "hook_zh": "SpaceX刚刚公布了轰动一时的第三季度数据，亏损达到44亿美元的净收入，股价飙升超过15% ，至163美元。", "summary_en": "The company reported $14.6 billion in Q3 revenue, up 161% from last year and beating forecasts of $12.7 billion, with Super Intelligence revenue exploding 830% to $7.6 billion and Starlink hitting 13.6 million subscribers. JPMorgan doubled its price target to $500, projecting $254 billion in 2027 revenue and 10 gigawatts of AI computing power, while others like Cantor Fitzgerald ($345) and Barclays ($300) followed suit. Merger talk with Tesla heated up too, with hypothetical deals valued at $420-$550 per share; Elon Musk called it 'Interesting,' though special committees are reviewing and no deal is certain.", "summary_zh": "收入达到146亿美元，比去年增长161% ，其中超级智能AI部门收入76亿美元， Starlink的1360万用户收入52亿美元，发布收入18亿美元。华尔街反应迅速，摩根大通将目标价翻了一番，达到500美元，康托尔·菲茨杰拉德(Cantor Fitzgerald)和巴克莱(Barclays)等其他公司也提高了目标价。 强劲的结果推动了与特斯拉的合并谈判，正如埃隆·马斯克（ Elon Musk ）指出的那样，特别委员会正在审查人工智能协同作用的潜在组合，尽管他被回避并且没有达成协议。", "body_en": "SpaceX Shares Surge 15% on Record Q3 Profits and AI Boom.\n\nSpaceX just posted blockbuster third-quarter numbers, flipping a loss into $4.4 billion in net income and sending shares soaring over 15% to $163.\n\nRevenue hit $14.6 billion, up 161% from last year, driven by $7.6 billion from its Super Intelligence AI segment, $5.2 billion from Starlink's 13.6 million subscribers, and $1.8 billion from launches.\n\nWall Street responded fast, with JPMorgan doubling its price target to $500 and others like Cantor Fitzgerald and Barclays lifting theirs too. The strong results fueled merger talk with Tesla, as Elon Musk noted special committees are reviewing a potential combination for AI synergies, though he is recused and no deal is set.", "body_zh": "SpaceX刚刚公布了轰动一时的第三季度数据，亏损达到44亿美元的净收入，股价飙升超过15% ，至163美元。\n\n收入达到146亿美元，比去年增长161% ，其中超级智能AI部门收入76亿美元， Starlink的1360万用户收入52亿美元，发布收入18亿美元。\n\n华尔街反应迅速，摩根大通将目标价翻了一番，达到500美元，康托尔·菲茨杰拉德(Cantor Fitzgerald)和巴克莱(Barclays)等其他公司也提高了目标价。强劲的结果推动了与特斯拉的合并谈判，正如埃隆·马斯克（ Elon Musk ）指出的那样，特别委员会正在审查人工智能协同作用的潜在组合，尽管他被回避并且没有达成协议。", "url": "https://x.com/i/trending/2112974495564865717", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "Space"], "updated_at": "2026-10-21T20:52:41.000Z"}, {"id": "2112319265076367697", "domain": "商业", "title_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day", "title_zh": "Jio Platforms IPO在开幕当天100分钟内全额认购", "hook_en": "Reliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.", "hook_zh": "Reliance Industries的大规模Jio Platforms IPO在短短100分钟内就达到了全额认购，机构和员工都纷纷投标。", "summary_en": "The ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff. Qualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "summary_zh": "₹ 30,213亿卢比的发行于10月21日开始，每股₹ 1,065- ₹ 1,119 ，旨在偿还高达₹ 27,500亿卢比的Jio电信债务，同时通过预支420万员工的早期工资来提高员工士气。合格的机构买家带头收费，提前超额认购配额，并将总需求量推高至当天的三倍。 Zerodha的Nithin Kamath认为， Jio经济实惠的数据使数百万人上网，印度的投资者基础从2016年的2亿卢比增长到今天的逾13亿卢比，这标志着这是近期历史上规模最大、认购速度最快的IPO。", "body_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day.\n\nReliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.\n\nThe ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff.\n\nQualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "body_zh": "Reliance Industries的大规模Jio Platforms IPO在短短100分钟内就达到了全额认购，机构和员工都纷纷投标。\n\n₹ 30,213亿卢比的发行于10月21日开始，每股₹ 1,065- ₹ 1,119 ，旨在偿还高达₹ 27,500亿卢比的Jio电信债务，同时通过预支420万员工的早期工资来提高员工士气。\n\n合格的机构买家带头收费，提前超额认购配额，并将总需求量推高至当天的三倍。Zerodha的Nithin Kamath认为， Jio经济实惠的数据使数百万人上网，印度的投资者基础从2016年的2亿卢比增长到今天的逾13亿卢比，这标志着这是近期历史上规模最大、认购速度最快的IPO。", "url": "https://x.com/i/trending/2112319265076367697", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:35:07.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标准普尔500指数前15大股票创下46.7%的份额纪录", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。 虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。", "body_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。\n\n15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。\n\n前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112795004678676841", "domain": "商业", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z"}, {"id": "2112781652112064634", "domain": "商业", "title_en": "BNB Standard Rings Nasdaq Bell After Rebrand and New CEO", "title_zh": "BNB Standard在品牌重塑和新任首席执行官之后响起纳斯达克钟声", "hook_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.", "hook_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。", "summary_en": "The Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls. New CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "summary_zh": "这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。 BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。", "body_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.\n\nThe Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls.\n\nNew CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "body_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。\n\n这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。\n\n新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。", "url": "https://x.com/i/trending/2112781652112064634", "category": "News", "topics": ["Business & Finance", "Cryptocurrency"], "updated_at": "2026-10-21T08:28:42.000Z"}, {"id": "2112915461406957899", "domain": "商业", "title_en": "Indian Markets Dip Despite Heavy Institutional Buying", "title_zh": "尽管机构购买量很大，但印度市场仍在下跌", "hook_en": "Institutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'", "hook_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”", "summary_en": "On October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling. Market breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "summary_zh": "2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。 这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "body_en": "Indian Markets Dip Despite Heavy Institutional Buying.\n\nInstitutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'\n\nOn October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling.\n\nMarket breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "body_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”\n\n2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。\n\n各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "url": "https://x.com/i/trending/2112915461406957899", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T18:35:48.000Z"}, {"id": "2112633705877340245", "domain": "商业", "title_en": "Anthropic Reports $80 Billion Net Loss in Draft IPO Filing", "title_zh": "Anthropic报告IPO申请草稿亏损$ 807亿", "hook_en": "Anthropic's draft IPO papers revealed an $80 billion net loss for early 2026, mostly from accounting charges as its value soared. The numbers highlight the huge bets powering AI's rise.", "hook_zh": "Anthropic的IPO文件草案显示，尽管收入为163亿美元，但2026年初的净亏损达到惊人的807亿美元，这一数字让人们谈论构建前沿人工智能的真实成本。", "summary_en": "The San Francisco company behind Claude AI models posted $16.3 billion in revenue for the first half of 2026, up sharply from $1.1 billion a year earlier, but racked up nearly $9 billion in compute spending. The massive loss largely came from $72 billion in non-cash charges on convertible notes amid rising valuation. The filing details $450 billion in long-term cloud deals with Google, AWS, and Microsoft, plus risks like customer concentration and potential AI catastrophes, as Anthropic eyes a public debut soon.", "summary_zh": "Claude背后的人工智能公司在2026年上半年的收入为163亿美元，比一年前的11亿美元大幅增加，但净亏损为807亿美元，主要来自融资的非现金会计调整。 运营支出包括近90亿美元的计算和基础设施支出，超过2025年全年，长期云交易总额约为4500亿美元，其中1110亿美元来自谷歌云， 1100亿美元来自AWS。该文件强调了计算竞争、仅来自两个主要客户的收入以及人工智能危害的潜在责任等风险，因为Anthropic很快就会公开上市。", "body_en": "Anthropic's draft IPO papers revealed a staggering $80.7 billion net loss for early 2026, despite $16.3 billion in revenue—a number that has people talking about the true cost of building frontier AI.\n\nThe AI company behind Claude posted $16.3 billion in revenue for the first half of 2026, up sharply from $1.1 billion a year before, but recorded an $80.7 billion net loss mostly from non-cash accounting adjustments on financing.\n\nOperating expenses included nearly $9 billion on compute and infrastructure, exceeding all of 2025, with long-term cloud deals totaling around $450 billion—including $111 billion with Google Cloud and $110 billion with AWS. The filing highlights risks like competition for compute, revenue from just two major customers, and potential liabilities from AI harms, as Anthropic eyes a public listing soon.", "body_zh": "Anthropic的IPO文件草案显示，尽管收入为163亿美元，但2026年初的净亏损达到惊人的807亿美元，这一数字让人们谈论构建前沿人工智能的真实成本。\n\nClaude背后的人工智能公司在2026年上半年的收入为163亿美元，比一年前的11亿美元大幅增加，但净亏损为807亿美元，主要来自融资的非现金会计调整。\n\n运营支出包括近90亿美元的计算和基础设施支出，超过2025年全年，长期云交易总额约为4500亿美元，其中1110亿美元来自谷歌云， 1100亿美元来自AWS。该文件强调了计算竞争、仅来自两个主要客户的收入以及人工智能危害的潜在责任等风险，因为Anthropic很快就会公开上市。", "url": "https://x.com/i/trending/2112633705877340245", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T21:06:11.000Z"}, {"id": "2112213032193372268", "domain": "商业", "title_en": "Town Raises $108 Million at $1 Billion Valuation for Team AI Assistants", "title_zh": "Town 融资 1.08 亿美元，估值达 10 亿美元，主打团队 AI 助手", "hook_en": "Imagine AI helpers that don't just manage your inbox but chat with your teammates' assistants to keep projects moving without the wait.", "hook_zh": "设想一下：AI 助手不仅管邮箱，还能与同事的助手直接沟通，减少项目等待。", "summary_en": "Town, an AI startup, secured $108 million in Series B funding, co-led by Forerunner Ventures and Menlo Ventures, pushing its valuation to $1 billion. The company launched its public product in June, hitting seven figures in annual recurring revenue with paying customers growing fourfold since July. Townies connect to workplace tools, learn individual styles, and now coordinate directly with each other for smoother team handoffs—addressing CEO Jean-Denis Greze's point that work's biggest bottleneck is waiting on others. Investors like Menlo Ventures, which uses it firm-wide, praise the focus on real tasks and rapid adoption across thousands of businesses.", "summary_zh": "AI 初创公司 Town 完成 1.08 亿美元 B 轮融资，由 Forerunner Ventures 与 Menlo Ventures 联合领投，估值升至 10 亿美元。产品于 6 月公开上线，年经常性收入已达七位数，付费客户自 7 月以来增长约四倍。Townies 可连接职场工具、学习个人风格，并彼此协调交接——回应 CEO Jean-Denis Greze 所说，工作最大瓶颈往往是「等别人」。Menlo 等投资人已全员使用，称其聚焦真实任务、落地很快。", "body_en": "Town Raises $108 Million at $1 Billion Valuation for Team AI Assistants.\n\nImagine AI helpers that don't just manage your inbox but chat with your teammates' assistants to keep projects moving without the wait.\n\nTown, an AI startup, secured $108 million in Series B funding, co-led by Forerunner Ventures and Menlo Ventures, pushing its valuation to $1 billion. The company launched its public product in June, hitting seven figures in annual recurring revenue with paying customers growing fourfold since July.\n\nTownies connect to workplace tools, learn individual styles, and now coordinate directly with each other for smoother team handoffs—addressing CEO Jean-Denis Greze's point that work's biggest bottleneck is waiting on others. Investors like Menlo Ventures, which uses it firm-wide, praise the focus on real tasks and rapid adoption across thousands of businesses.", "body_zh": "Town 融资 1.08 亿美元，估值达 10 亿美元，主打团队 AI 助手。\n\n设想一下：AI 助手不仅管邮箱，还能与同事的助手直接沟通，减少项目等待。\n\nAI 初创公司 Town 完成 1.08 亿美元 B 轮融资，由 Forerunner Ventures 与 Menlo Ventures 联合领投，估值升至 10 亿美元。产品于 6 月公开上线，年经常性收入已达七位数，付费客户自 7 月以来增长约四倍。\n\nTownies 可连接职场工具、学习个人风格，并彼此协调交接——回应 CEO Jean-Denis Greze 所说，工作最大瓶颈往往是「等别人」。Menlo 等投资人已全员使用，称其聚焦真实任务、落地很快。", "url": "https://x.com/i/trending/2112213032193372268", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-19T21:18:43.000Z"}, {"id": "2112948932623978868", "domain": "商业", "title_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026", "title_zh": "印度核心产业在2026年9月创下30个月新高，增长7.9%", "hook_en": "India's factories and mines powered up in September, delivering their strongest output in over two years.", "hook_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。", "summary_en": "Core industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%. While fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "summary_zh": "核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。 这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "body_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026.\n\nIndia's factories and mines powered up in September, delivering their strongest output in over two years.\n\nCore industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%.\n\nWhile fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "body_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。\n\n核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。\n\n虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "url": "https://x.com/i/trending/2112948932623978868", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:58:30.000Z"}, {"id": "2112958295606804950", "domain": "商业", "title_en": "Tonbo Imaging and Bonfiglioli IPO Allotments Bring Mixed Results for Investors", "title_zh": "Tonbo Imaging 与 Bonfiglioli IPO 中签结果冷热不均", "hook_en": "Vibhor Varshney could hardly believe his luck, posting 'Finally kuch mila 😂😂 Got something in tonbo 😍' after securing shares in the hotly contested IPO.", "hook_zh": "投资者 Vibhor Varshney 中签后惊喜发帖：终于在超抢手的 Tonbo 新股里分到一杯羹。", "summary_en": "On October 21, 2026, investors checked allotment results for Tonbo Imaging India's ₹852 crore defence electronics IPO, oversubscribed 135.9 times with retail odds of 1 in 25, and Bonfiglioli Transmissions' ₹2,533 crore industrial IPO, subscribed 46 times with 1 in 5 retail chances. Some like Jeet Chetwani got 1 out of 4 or 5 applications, while Swing Trader Adi celebrated a third straight win, sharing screenshots of 'Allotted' green tags for 21 Tonbo shares or 25 Bonfiglioli lots. Shares credit to demat accounts on October 22, refunds process that day, and listings hit BSE and NSE on October 23 amid grey market premiums hinting at gains.", "summary_zh": "2026年10月21日，投资者陆续查询中签结果：印度国防电子公司 Tonbo Imaging 约852亿卢比IPO获135.9倍超额认购，散户中签概率约1/25；工业传动企业 Bonfiglioli Transmissions 约2533亿卢比IPO获46倍认购，散户约1/5机会。有人多账户仅中1签，也有交易者连中三签并晒出绿色“已配售”截图。股份将于10月22日进入 demat 账户，同日处理退款，10月23日登陆孟买证交所与印度国家证交所，灰市溢价暗示上市可能有盈利空间。", "body_en": "Tonbo Imaging and Bonfiglioli IPO Allotments Bring Mixed Results for Investors.\n\nVibhor Varshney could hardly believe his luck, posting 'Finally kuch mila 😂😂 Got something in tonbo 😍' after securing shares in the hotly contested IPO.\n\nOn October 21, 2026, investors checked allotment results for Tonbo Imaging India's ₹852 crore defence electronics IPO, oversubscribed 135.9 times with retail odds of 1 in 25, and Bonfiglioli Transmissions' ₹2,533 crore industrial IPO, subscribed 46 times with 1 in 5 retail chances.\n\nSome like Jeet Chetwani got 1 out of 4 or 5 applications, while Swing Trader Adi celebrated a third straight win, sharing screenshots of 'Allotted' green tags for 21 Tonbo shares or 25 Bonfiglioli lots. Shares credit to demat accounts on October 22, refunds process that day, and listings hit BSE and NSE on October 23 amid grey market premiums hinting at gains.", "body_zh": "Tonbo Imaging 与 Bonfiglioli IPO 中签结果冷热不均。\n\n投资者 Vibhor Varshney 中签后惊喜发帖：终于在超抢手的 Tonbo 新股里分到一杯羹。\n\n2026年10月21日，投资者陆续查询中签结果：印度国防电子公司 Tonbo Imaging 约852亿卢比IPO获135.9倍超额认购，散户中签概率约1/25；工业传动企业 Bonfiglioli Transmissions 约2533亿卢比IPO获46倍认购，散户约1/5机会。\n\n有人多账户仅中1签，也有交易者连中三签并晒出绿色“已配售”截图。股份将于10月22日进入 demat 账户，同日处理退款，10月23日登陆孟买证交所与印度国家证交所，灰市溢价暗示上市可能有盈利空间。", "url": "https://x.com/i/trending/2112958295606804950", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T20:40:20.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕，纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。", "body_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕，纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。\n\n第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112575525655081471", "domain": "中国", "title_en": "Bipartisan Ex-Officials Push Energy Permitting Reform to Counter China", "title_zh": "两党前官员推动能源许可改革以对抗中国", "hook_en": "Nineteen top officials from both parties, including Janet Yellen and Mike Pompeo, joined forces in a letter warning that slow U.S. infrastructure builds risk losing ground to China.", "hook_zh": "包括珍妮特·耶伦(Janet Yellen)和迈克·蓬佩奥(Mike Pompeo)在内的19名来自两党的高级官员联手发出一封信，警告说，美国基础设施建设的缓慢可能会让中国", "summary_en": "The group, spanning Clinton to Biden administrations, sent the letter to congressional leaders urging passage of the Bipartisan American Affordability and Jobs Act to speed up energy project permitting. They highlight how U.S. power plant timelines have doubled to over four years, while China has built more high-voltage transmission in 15 years than America has in its history, and now leads in tech manufacturing. The reform would streamline transmission planning, grid connections, and litigation while keeping community input, aiming to boost sectors like AI and semiconductors amid rising electricity demand.", "summary_zh": "该组织跨越克林顿和拜登政府，向国会领导人发出信件，敦促通过两党的“美国负担能力和就业法案” ，以加快能源项目的许可。他们强调了美国发电厂的时间表在四年内翻了一番，而中国在15年内建造了比美国历史上更多的高压输电，现在在科技制造业中处于领先地位。 这项改革将简化传输规划、电网连接和诉讼，同时保持社区投入，旨在在不断增长的电力需求中促进人工智能和半导体等行业的发展。", "body_en": "Bipartisan Ex-Officials Push Energy Permitting Reform to Counter China.\n\nNineteen top officials from both parties, including Janet Yellen and Mike Pompeo, joined forces in a letter warning that slow U.S. infrastructure builds risk losing ground to China.\n\nThe group, spanning Clinton to Biden administrations, sent the letter to congressional leaders urging passage of the Bipartisan American Affordability and Jobs Act to speed up energy project permitting. They highlight how U.S.\n\npower plant timelines have doubled to over four years, while China has built more high-voltage transmission in 15 years than America has in its history, and now leads in tech manufacturing. The reform would streamline transmission planning, grid connections, and litigation while keeping community input, aiming to boost sectors like AI and semiconductors amid rising electricity demand.", "body_zh": "包括珍妮特·耶伦(Janet Yellen)和迈克·蓬佩奥(Mike Pompeo)在内的19名来自两党的高级官员联手发出一封信，警告说，美国基础设施建设的缓慢可能会让中国\n\n该组织跨越克林顿和拜登政府，向国会领导人发出信件，敦促通过两党的“美国负担能力和就业法案” ，以加快能源项目的许可。\n\n他们强调了美国发电厂的时间表在四年内翻了一番，而中国在15年内建造了比美国历史上更多的高压输电，现在在科技制造业中处于领先地位。这项改革将简化传输规划、电网连接和诉讼，同时保持社区投入，旨在在不断增长的电力需求中促进人工智能和半导体等行业的发展。", "url": "https://x.com/i/trending/2112575525655081471", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T16:14:33.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Chinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。\n\n以上内容根据公开讨论与报道梳理，详情可在 X 原文页继续跟踪进展。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2112895365657567737", "domain": "中国", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112336528253047290", "domain": "中国", "title_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control", "title_zh": "自动驾驶与手控驾驶之争升温", "hook_en": "Fitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.", "hook_zh": "健身教练 Jason Helmes 抛出「婴儿潮一代」式看法：他爱握方向盘、轰着音乐、在路上不看屏幕地放松。", "summary_en": "People are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S. robotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "summary_zh": "公众对自动驾驶态度分裂：有人珍视亲手开车带来的精神放松，也有人欢迎腾出手来聊天、阅读或小憩。Waymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据顾虑。乘客已赞赏在特斯拉 Cybercab 里喝咖啡、减轻拥堵压力等体验，但许多人仍留恋手控驾驶的简单乐趣，设想娱乐路段手开、通勤路段自动驾驶的组合。", "body_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control.\n\nFitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.\n\nPeople are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S.\n\nrobotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "body_zh": "自动驾驶与手控驾驶之争升温。\n\n健身教练 Jason Helmes 抛出「婴儿潮一代」式看法：他爱握方向盘、轰着音乐、在路上不看屏幕地放松。\n\n公众对自动驾驶态度分裂：有人珍视亲手开车带来的精神放松，也有人欢迎腾出手来聊天、阅读或小憩。\n\nWaymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据顾虑。乘客已赞赏在特斯拉 Cybercab 里喝咖啡、减轻拥堵压力等体验，但许多人仍留恋手控驾驶的简单乐趣，设想娱乐路段手开、通勤路段自动驾驶的组合。", "url": "https://x.com/i/trending/2112336528253047290", "category": "News", "topics": ["Technology", "Robotics"], "updated_at": "2026-10-20T00:20:46.000Z"}, {"id": "2112538623471964597", "domain": "中国", "title_en": "USDA Confirms Major Soybean Export Sale to China", "title_zh": "美国农业部确认对华大豆大额出口销售", "hook_en": "Farmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.", "hook_zh": "农业部宣布美国大豆对华私人大额成交，数月沉寂后首现明显恢复采购信号。", "summary_en": "Private exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million. For January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "summary_zh": "出口商报告向中国出售 61.2 万吨 2026/27 市场年美国大豆，为近期最大单日成交之一。中国海关显示 9 月首批美国大豆到港 36.0878 万吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美国对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨；近期数据则显示贸易条件改善下美国货源回升。", "body_en": "USDA Confirms Major Soybean Export Sale to China.\n\nFarmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.\n\nPrivate exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million.\n\nFor January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "body_zh": "美国农业部确认对华大豆大额出口销售。\n\n农业部宣布美国大豆对华私人大额成交，数月沉寂后首现明显恢复采购信号。\n\n出口商报告向中国出售 61.2 万吨 2026/27 市场年美国大豆，为近期最大单日成交之一。\n\n中国海关显示 9 月首批美国大豆到港 36.0878 万吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美国对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨；近期数据则显示贸易条件改善下美国货源回升。", "url": "https://x.com/i/trending/2112538623471964597", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T13:42:34.000Z"}, {"id": "2112684363427312051", "domain": "中国", "title_en": "RFK Jr. Pushes Regulated Marketplace for Peptides", "title_zh": "RFK Jr. 推动建立受监管的肽类药物市场", "hook_en": "Americans are already turning to peptides for everything from muscle growth to anti-aging, often from unregulated overseas sources. U.S. Health Secretary Robert F. Kennedy Jr. wants to bring that demand into safer, inspected channels.", "hook_zh": "美国人已在用肽类药物增肌、抗衰老，货源多来自海外灰色渠道。美国卫生部长小罗伯特·肯尼迪希望把需求纳入更安全、可监管的通路。", "summary_en": "In a Fox News interview, Kennedy highlighted the $1.5 billion to $3 billion gray-market peptide trade, mostly from Chinese firms lacking FDA oversight, which raises worries about purity and fake products. He urged the Trump administration to create a regulated U.S. marketplace, emphasizing freedom of choice with guaranteed safety. The push aligns with a proposed FDA policy to let compounding pharmacies produce certain peptides like BPC-157 under supervision, though critics caution about limited safety evidence and risks to younger users experimenting after online promotions.", "summary_zh": "肯尼迪在福克斯新闻采访中指出，灰色市场肽类交易规模约15亿至30亿美元，大多来自缺乏FDA监管的中国企业，纯度与假货风险引发担忧。他敦促特朗普政府建立受监管的美国市场，在保障安全的前提下保留选择自由。此举与拟议的FDA政策方向一致，允许复配药房在监管下生产如BPC-157等肽类；批评者则警告安全性证据有限，年轻用户受网络营销影响盲目尝试存在风险。", "body_en": "RFK Jr. Pushes Regulated Marketplace for Peptides.\n\nAmericans are already turning to peptides for everything from muscle growth to anti-aging, often from unregulated overseas sources. U.S. Health Secretary Robert F. Kennedy Jr. wants to bring that demand into safer, inspected channels.\n\nIn a Fox News interview, Kennedy highlighted the $1.5 billion to $3 billion gray-market peptide trade, mostly from Chinese firms lacking FDA oversight, which raises worries about purity and fake products. He urged the Trump administration to create a regulated U.S.\n\nmarketplace, emphasizing freedom of choice with guaranteed safety. The push aligns with a proposed FDA policy to let compounding pharmacies produce certain peptides like BPC-157 under supervision, though critics caution about limited safety evidence and risks to younger users experimenting after online promotions.", "body_zh": "RFK Jr. 推动建立受监管的肽类药物市场。\n\n美国人已在用肽类药物增肌、抗衰老，货源多来自海外灰色渠道。美国卫生部长小罗伯特·肯尼迪希望把需求纳入更安全、可监管的通路。\n\n肯尼迪在福克斯新闻采访中指出，灰色市场肽类交易规模约15亿至30亿美元，大多来自缺乏FDA监管的中国企业，纯度与假货风险引发担忧。\n\n他敦促特朗普政府建立受监管的美国市场，在保障安全的前提下保留选择自由。此举与拟议的FDA政策方向一致，允许复配药房在监管下生产如BPC-157等肽类；批评者则警告安全性证据有限，年轻用户受网络营销影响盲目尝试存在风险。", "url": "https://x.com/i/trending/2112684363427312051", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T04:38:25.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。\n\n菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112579117904535807", "domain": "中国", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料。\n\n美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。\n\n美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112101207397601450", "domain": "国际", "title_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks", "title_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰", "hook_en": "As Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.", "hook_zh": "乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。", "summary_en": "Ukrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned. Critics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "summary_zh": "尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "body_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks.\n\nAs Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.\n\nUkrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned.\n\nCritics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "body_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰。\n\n乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。\n\n尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "url": "https://x.com/i/trending/2112101207397601450", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:28:55.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2113011795937865915", "domain": "国际", "title_en": "Ireland's Parliament Narrows Approves Triple Lock Reform on Defence Deployments", "title_zh": "爱尔兰议会以微弱优势通过“三重锁定”防务改革", "hook_en": "After hours of heated debate, Ireland's Dáil voted 79-71 to loosen rules that have long guided its troops overseas, keeping government and parliamentary checks but dropping the UN veto.", "hook_zh": "经过数小时激烈辩论，爱尔兰众议院以79票对71票通过放宽海外派兵规则：保留政府与议会把关，但取消联合国一票否决。", "summary_en": "The Defence (Amendment) Bill 2026 removes the United Nations Security Council mandate from the Triple Lock, which previously required cabinet, Dáil, and UN approval for missions with more than 12 troops. Supporters like Taoiseach Micheál Martin and Defence Minister Helen McEntee argue the change lets Ireland sustain its 60-year peacekeeping tradition without relying on a gridlocked UN, especially amid vetoes from nations like Russia. Opposition leaders such as Sinn Féin's Mary Lou McDonald call it a betrayal of neutrality without a public vote, backed by polls showing 44 percent favour keeping the Triple Lock intact. The bill heads to committee next month, with critics pushing for wider consultation on this shift in foreign policy.", "summary_zh": "《2026年国防（修正）法案》将联合国安理会授权从“三重锁定”中移除；此前超过12人的海外任务需内阁、众议院与联合国三方批准。总理马丁、国防部长麦肯蒂等支持者称，此举可让爱尔兰在联合国陷入僵局、尤其是俄方否决频发时，继续维持六十余年维和传统。新芬党领袖麦克唐纳等反对派斥其为未经公投的中立立场背叛，民调显示约44%民众希望保留原机制。法案下月进入委员会审议，批评者呼吁就外交政策转向展开更广泛磋商。", "body_en": "Ireland's Parliament Narrows Approves Triple Lock Reform on Defence Deployments.\n\nAfter hours of heated debate, Ireland's Dáil voted 79-71 to loosen rules that have long guided its troops overseas, keeping government and parliamentary checks but dropping the UN veto.\n\nThe Defence (Amendment) Bill 2026 removes the United Nations Security Council mandate from the Triple Lock, which previously required cabinet, Dáil, and UN approval for missions with more than 12 troops. Supporters like Taoiseach Micheál Martin and Defence Minister Helen McEntee argue the change lets Ireland sustain its 60-year peacekeeping tradition without relying on a gridlocked UN, especially amid vetoes from nations like Russia.\n\nOpposition leaders such as Sinn Féin's Mary Lou McDonald call it a betrayal of neutrality without a public vote, backed by polls showing 44 percent favour keeping the Triple Lock intact. The bill heads to committee next month, with critics pushing for wider consultation on this shift in foreign policy.", "body_zh": "爱尔兰议会以微弱优势通过“三重锁定”防务改革。\n\n经过数小时激烈辩论，爱尔兰众议院以79票对71票通过放宽海外派兵规则：保留政府与议会把关，但取消联合国一票否决。\n\n《2026年国防（修正）法案》将联合国安理会授权从“三重锁定”中移除；此前超过12人的海外任务需内阁、众议院与联合国三方批准。总理马丁、国防部长麦肯蒂等支持者称，此举可让爱尔兰在联合国陷入僵局、尤其是俄方否决频发时，继续维持六十余年维和传统。\n\n新芬党领袖麦克唐纳等反对派斥其为未经公投的中立立场背叛，民调显示约44%民众希望保留原机制。法案下月进入委员会审议，批评者呼吁就外交政策转向展开更广泛磋商。", "url": "https://x.com/i/trending/2113011795937865915", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T21:05:15.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。\n\n爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112602589699436902", "domain": "国际", "title_en": "Trump Team Proposes U.S. Control of Frozen Russian Assets, Europe Rejects", "title_zh": "特朗普团队提议美方掌控冻结俄资，欧洲拒绝", "hook_en": "In Miami talks, Steve Witkoff and Jared Kushner pitched shifting Europe's frozen Russian assets to a U.S.-run fund to lure peace negotiations on Ukraine. European delegates shut it down fast.", "hook_zh": "迈阿密会谈中，威特科夫与库什纳提议把欧洲冻结的俄资产转入美方基金以换和谈，欧方迅速否决。", "summary_en": "The Trump administration suggested moving part of the €260 billion in immobilized Russian assets—mostly held in the EU, like €202 billion at Belgium's Euroclear—into a Washington-controlled vehicle to restart Ukraine talks with officials from Ukraine, Britain, France, Germany, the EU, and NATO. European representatives firmly opposed giving up control or returning funds to Moscow, with German Chancellor Friedrich Merz insisting the assets stay frozen in Europe. The plan drew surprise in Kyiv and sharp online backlash, with critics calling it outrageous and urging direct aid to Ukraine instead. It underscores growing U.S.-Europe divides on using the assets for leverage versus incentives.", "summary_zh": "特朗普政府建议将约 2600 亿欧元被冻结俄资产（多数在欧盟，比利时 Euroclear 约持 2020 亿）的一部分转入华盛顿主导载体，以重启与乌克兰、英法德、欧盟及北约官员的和谈。欧洲代表坚决反对交出控制权或向莫斯科返还资金，德国总理默茨强调资产应继续冻结在欧洲。基辅方面感意外，网上批评声浪大，呼吁直接援助乌克兰。事件凸显美欧在「杠杆」与「激励」用法上的分歧。", "body_en": "Trump Team Proposes U.S. Control of Frozen Russian Assets, Europe Rejects.\n\nIn Miami talks, Steve Witkoff and Jared Kushner pitched shifting Europe's frozen Russian assets to a U.S.-run fund to lure peace negotiations on Ukraine. European delegates shut it down fast.\n\nThe Trump administration suggested moving part of the €260 billion in immobilized Russian assets—mostly held in the EU, like €202 billion at Belgium's Euroclear—into a Washington-controlled vehicle to restart Ukraine talks with officials from Ukraine, Britain, France, Germany, the EU, and NATO. European representatives firmly opposed giving up control or returning funds to Moscow, with German Chancellor Friedrich Merz insisting the assets stay frozen in Europe.\n\nThe plan drew surprise in Kyiv and sharp online backlash, with critics calling it outrageous and urging direct aid to Ukraine instead. It underscores growing U.S.-Europe divides on using the assets for leverage versus incentives.", "body_zh": "特朗普团队提议美方掌控冻结俄资，欧洲拒绝。\n\n迈阿密会谈中，威特科夫与库什纳提议把欧洲冻结的俄资产转入美方基金以换和谈，欧方迅速否决。\n\n特朗普政府建议将约 2600 亿欧元被冻结俄资产（多数在欧盟，比利时 Euroclear 约持 2020 亿）的一部分转入华盛顿主导载体，以重启与乌克兰、英法德、欧盟及北约官员的和谈。欧洲代表坚决反对交出控制权或向莫斯科返还资金，德国总理默茨强调资产应继续冻结在欧洲。\n\n基辅方面感意外，网上批评声浪大，呼吁直接援助乌克兰。事件凸显美欧在「杠杆」与「激励」用法上的分歧。", "url": "https://x.com/i/trending/2112602589699436902", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T00:39:08.000Z"}, {"id": "2112994548645540037", "domain": "国际", "title_en": "National Security Officials Prep States for Potential Trump Midterm Interference", "title_zh": "国家安全官员为潜在的特朗普中期干预做好准备", "hook_en": "A handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.", "hook_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。", "summary_en": "The Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms. They focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "summary_zh": "《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。他们专注于预防措施，担心民主规范，没有党派动机。 批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "body_en": "National Security Officials Prep States for Potential Trump Midterm Interference.\n\nA handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.\n\nThe Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms.\n\nThey focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "body_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。\n\n《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。\n\n他们专注于预防措施，担心民主规范，没有党派动机。批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "url": "https://x.com/i/trending/2112994548645540037", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:43.000Z"}, {"id": "2112893265104007427", "domain": "国际", "title_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms", "title_zh": "帖文曝光组织在中期选举前讨论应对联邦行动", "hook_en": "A detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.", "hook_zh": "一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。", "summary_en": "X user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in. This coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "summary_zh": "X 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "body_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms.\n\nA detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.\n\nX user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in.\n\nThis coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "body_zh": "帖文曝光组织在中期选举前讨论应对联邦行动。\n\n一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。\n\nX 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。\n\n同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "url": "https://x.com/i/trending/2112893265104007427", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:32:37.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻断乌克兰与摩尔多瓦入盟下一阶段谈判", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈牙利语少数族裔相关法律数日，匈牙利却叫停乌、摩入盟谈判下一阶段，令各方错愕。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前入盟程序本有进展。布达佩斯强调少数族裔权益与能源等关切；基辅与伙伴批评政治化拖延。摩尔多瓦同步受阻，凸显扩大进程中的一票否决张力。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻断乌克兰与摩尔多瓦入盟下一阶段谈判。\n\n乌克兰刚通过保护匈牙利语少数族裔相关法律数日，匈牙利却叫停乌、摩入盟谈判下一阶段，令各方错愕。\n\n10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前入盟程序本有进展。\n\n布达佩斯强调少数族裔权益与能源等关切；基辅与伙伴批评政治化拖延。摩尔多瓦同步受阻，凸显扩大进程中的一票否决张力。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112964655136354409", "domain": "国际", "title_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution", "title_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助", "hook_en": "A regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.", "hook_zh": "利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。", "summary_en": "The Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others. Polish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "summary_zh": "利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "body_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution.\n\nA regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.\n\nThe Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others.\n\nPolish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "body_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助。\n\n利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。\n\n利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。\n\n波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "url": "https://x.com/i/trending/2112964655136354409", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:57:58.000Z"}, {"id": "2112948936755286232", "domain": "国际", "title_en": "JD Vance Questions US Obligations to Ukraine Amid Budapest Memorandum Debate", "title_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点", "hook_en": "JD Vance called Ukraine a partner, not an ally, with no formal obligation to defend it. That statement quickly brought back memories of a 1994 promise Ukraine trusted when it gave up its nuclear arsenal.", "hook_zh": "万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。", "summary_en": "In an October 20, 2026 interview, US Vice President JD Vance said America has no treaty-bound duty to stand by Ukraine. Many pointed to the 1994 Budapest Memorandum, where Ukraine surrendered about 4,400 nuclear warheads in exchange for security assurances from the US, Russia, and the UK—assurances that respected its sovereignty and borders but lacked binding military commitments like NATO's Article 5. While the US has sent billions in aid since Russia's 2014 Crimea annexation and 2022 invasion, the debate highlights the memorandum's moral weight versus its non-binding nature, raising questions for nations weighing nuclear disarmament.", "summary_zh": "美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "body_en": "JD Vance Questions US Obligations to Ukraine Amid Budapest Memorandum Debate.\n\nJD Vance called Ukraine a partner, not an ally, with no formal obligation to defend it. That statement quickly brought back memories of a 1994 promise Ukraine trusted when it gave up its nuclear arsenal.\n\nIn an October 20, 2026 interview, US Vice President JD Vance said America has no treaty-bound duty to stand by Ukraine.\n\nMany pointed to the 1994 Budapest Memorandum, where Ukraine surrendered about 4,400 nuclear warheads in exchange for security assurances from the US, Russia, and the UK—assurances that respected its sovereignty and borders but lacked binding military commitments like NATO's Article 5. While the US has sent billions in aid since Russia's 2014 Crimea annexation and 2022 invasion, the debate highlights the memorandum's moral weight versus its non-binding nature, raising questions for nations weighing nuclear disarmament.", "body_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点。\n\n万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。\n\n美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。\n\n许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "url": "https://x.com/i/trending/2112948936755286232", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:44.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112558002708648142", "domain": "国际", "title_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism", "title_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议", "hook_en": "A 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.", "hook_zh": "一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。", "summary_en": "In a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws. The resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "summary_zh": "在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "body_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism.\n\nA 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.\n\nIn a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws.\n\nThe resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "body_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议。\n\n一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。\n\n在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。\n\n片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "url": "https://x.com/i/trending/2112558002708648142", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:59:26.000Z"}, {"id": "2112442700796690870", "domain": "国际", "title_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally", "title_zh": "乌克兰是否算美国「盟友」引网络激辩", "hook_en": "Congresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.", "hook_zh": "众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。", "summary_en": "The argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation. Posts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "summary_zh": "争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "body_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally.\n\nCongresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.\n\nThe argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation.\n\nPosts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "body_zh": "乌克兰是否算美国「盟友」引网络激辩。\n\n众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。\n\n争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。\n\n历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "url": "https://x.com/i/trending/2112442700796690870", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:56:58.000Z"}, {"id": "2112588449140355241", "domain": "体育", "title_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money", "title_zh": "洛杉矶酒吧联盟赌道奇出局对冲，6 万美元翻倍", "hook_en": "When the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.", "hook_zh": "道奇在联盟冠军赛出局后，球场附近 25 家酒吧并不慌——他们在预测市场下的 6 万美元对冲赔出 12 万。", "summary_en": "The Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit. The wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "summary_zh": "洛杉矶餐饮集团在 Kalshi 上下注道奇无法进世界系列赛，以对冲季后赛早早出局带来的客流损失。球队出局后赌注翻倍，约等于他们本指望多打几场多赚的营业额。观察者称这是预测市场充当“定制保险”的聪明案例，让依赖赛事人流的商家对冲体育风险。", "body_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money.\n\nWhen the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.\n\nThe Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit.\n\nThe wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "body_zh": "洛杉矶酒吧联盟赌道奇出局对冲，6 万美元翻倍。\n\n道奇在联盟冠军赛出局后，球场附近 25 家酒吧并不慌——他们在预测市场下的 6 万美元对冲赔出 12 万。\n\n洛杉矶餐饮集团在 Kalshi 上下注道奇无法进世界系列赛，以对冲季后赛早早出局带来的客流损失。\n\n球队出局后赌注翻倍，约等于他们本指望多打几场多赚的营业额。观察者称这是预测市场充当“定制保险”的聪明案例，让依赖赛事人流的商家对冲体育风险。", "url": "https://x.com/i/trending/2112588449140355241", "category": "News", "topics": ["Baseball"], "updated_at": "2026-10-21T01:55:22.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2112918027859554811", "domain": "体育", "title_en": "Curry Faces Dončić as Warriors Open Season at Lakers", "title_zh": "勇士队-湖人队2026-27赛季加利福尼亚交锋", "hook_en": "Stephen Curry heads into his 18th NBA season, posting 'Lock in #dubnation #year18' before facing Luka Dončić and a retooled Lakers squad at Crypto.com Arena.", "hook_zh": "斯蒂芬·库里的“锁定# dubnation # year18”帖子捕捉到了嗡嗡声，因为他进入了第18个赛季，在拥挤的Crypto.com竞技场中面对湖人队。", "summary_en": "The 2026-27 NBA season kicks off with the Golden State Warriors visiting the Los Angeles Lakers on ESPN at 7 p.m. PT, pitting 38-year-old Curry—probable despite ankle soreness—against Dončić on a Lakers team reshaped after LeBron James' free agency exit with additions like Walker Kessler and Collin Sexton. The Warriors face challenges with Jimmy Butler recovering from knee surgery and Moses Moody sidelined until January, leaning heavily on Curry's leadership. Fans from both sides shared their excitement, with the Warriors declaring 'WE’RE BAAAACK' and Lakers fans cheering that basketball is finally back in LA.", "summary_zh": "金州勇士队于周三晚上访问洛杉矶湖人队，启动2026-27赛季的NBA赛季，并于太平洋时间晚上7点在ESPN上发布消息。咖喱，可能尽管最近脚踝调整，领导一个人手不足的勇士队失踪吉米·巴特勒和摩西·穆迪，直到一月，而湖人队的球迷炒作他们最喜欢的主场。 从勇士队的“WE 'RE BAAAACK”到湖人队的“湖人篮球回归” ，双方都在网上分享了兴奋，这标志着库里在这场经典的竞争揭幕战中38岁的长寿。", "body_en": "Warriors-Lakers Tip Off 2026-27 NBA Season in California Clash.\n\nStephen Curry's 'Lock in #dubnation #year18' post captures the buzz as he heads into his 18th season, facing the Lakers in a packed Crypto.com Arena.\n\nThe Golden State Warriors visit the Los Angeles Lakers on Wednesday night to launch the 2026-27 NBA season, with tipoff at 7 pm PT on ESPN.\n\nCurry, probable despite a recent ankle tweak, leads a shorthanded Warriors squad missing Jimmy Butler and Moses Moody until January, while Lakers fans hype their home favorites. Both sides share excitement online, from Warriors' 'WE’RE BAAAACK' to Lakers' 'LAKERS BASKETBALL IS BACK,' marking Curry's longevity at age 38 in this classic rivalry opener.", "body_zh": "斯蒂芬·库里的“锁定# dubnation # year18”帖子捕捉到了嗡嗡声，因为他进入了第18个赛季，在拥挤的Crypto.com竞技场中面对湖人队。\n\n金州勇士队于周三晚上访问洛杉矶湖人队，启动2026-27赛季的NBA赛季，并于太平洋时间晚上7点在ESPN上发布消息。\n\n咖喱，可能尽管最近脚踝调整，领导一个人手不足的勇士队失踪吉米·巴特勒和摩西·穆迪，直到一月，而湖人队的球迷炒作他们最喜欢的主场。从勇士队的“WE 'RE BAAAACK”到湖人队的“湖人篮球回归” ，双方都在网上分享了兴奋，这标志着库里在这场经典的竞争揭幕战中38岁的长寿。", "url": "https://x.com/i/trending/2112918027859554811", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T21:05:42.000Z"}, {"id": "2112650194173022254", "domain": "体育", "title_en": "Chelsea's Clean-Sheet Wins Over PSG and Barcelona Resurface After Latest Clash", "title_zh": "在最近的冲突之后，切尔西的干净表格赢得了巴黎圣日耳曼和巴塞罗那的重新浮出水面", "hook_en": "Chelsea fans are reliving two unforgettable 3-0 triumphs from 2025, the only clean-sheet double over PSG and Barcelona in a single season.", "hook_zh": "切尔西球迷正在重温2025年的两次令人难忘的3-0胜利，这是巴黎圣日耳曼和巴塞罗那在一个赛季中唯一的干净比赛。", "summary_en": "Last year, Chelsea dominated PSG 3-0 in the FIFA Club World Cup final on July 13 at MetLife Stadium, with Cole Palmer scoring twice and assisting the third before a late red card left PSG with 10 men. Five months later on November 25 at Stamford Bridge in the Champions League, they beat Barcelona 3-0 via an own goal, Estêvão's stunner, and Liam Delap's finish, after another red card to Barcelona's captain. These feats are lighting up discussions following PSG's recent 4-2 win over Barcelona, with fans boasting Chelsea showed both rivals true levels while some recall an earlier 8-2 aggregate loss to PSG.", "summary_zh": "去年，切尔西在7月13日在大都会体育场举行的FIFA俱乐部世界杯决赛中以3-0领先PSG ，科尔·帕尔默两次得分，第三次助攻，之后红牌以10名男子离开PSG。五个月后的11月25日，在欧洲冠军联赛的斯坦福桥，他们以3比0击败巴塞罗那，以自己的进球、埃斯特旺的惊人成绩和利亚姆·德拉普的完赛，再次获得巴塞罗那队长的红牌。 在巴黎圣日耳曼队最近4-2战胜巴塞罗那后，这些壮举点燃了讨论，球迷吹嘘切尔西展示了两个对手的真实水平，而一些人回忆起早些时候8-2输给巴黎圣日耳曼队的情况。", "body_en": "Chelsea fans are reliving two unforgettable 3-0 triumphs from 2025, the only clean-sheet double over PSG and Barcelona in a single season.\n\nLast year, Chelsea dominated PSG 3-0 in the FIFA Club World Cup final on July 13 at MetLife Stadium, with Cole Palmer scoring twice and assisting the third before a late red card left PSG with 10 men.\n\nFive months later on November 25 at Stamford Bridge in the Champions League, they beat Barcelona 3-0 via an own goal, Estêvão's stunner, and Liam Delap's finish, after another red card to Barcelona's captain. These feats are lighting up discussions following PSG's recent 4-2 win over Barcelona, with fans boasting Chelsea showed both rivals true levels while some recall an earlier 8-2 aggregate loss to PSG.", "body_zh": "切尔西球迷正在重温2025年的两次令人难忘的3-0胜利，这是巴黎圣日耳曼和巴塞罗那在一个赛季中唯一的干净比赛。\n\n去年，切尔西在7月13日在大都会体育场举行的FIFA俱乐部世界杯决赛中以3-0领先PSG ，科尔·帕尔默两次得分，第三次助攻，之后红牌以10名男子离开PSG。\n\n五个月后的11月25日，在欧洲冠军联赛的斯坦福桥，他们以3比0击败巴塞罗那，以自己的进球、埃斯特旺的惊人成绩和利亚姆·德拉普的完赛，再次获得巴塞罗那队长的红牌。在巴黎圣日耳曼队最近4-2战胜巴塞罗那后，这些壮举点燃了讨论，球迷吹嘘切尔西展示了两个对手的真实水平，而一些人回忆起早些时候8-2输给巴黎圣日耳曼队的情况。", "url": "https://x.com/i/trending/2112650194173022254", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T19:57:53.000Z"}, {"id": "2112984435729576320", "domain": "体育", "title_en": "NFL Sticks with France Game Amid Paris Riots", "title_zh": "NFL在巴黎骚乱中与法国队比赛", "hook_en": "As riots grip Paris with clashes, looting, and arrests, the NFL readies its first regular-season game there, drawing sharp questions from players' families and critics.", "hook_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。", "summary_en": "The Pittsburgh Steelers face the New Orleans Saints at Stade de France on October 25, despite unrest from protests over living costs, school conditions, and public services that led to thousands of arrests and injuries. NFL Commissioner Roger Goodell insists the protests are mostly peaceful and players face no danger, with ramped-up stadium security coordinated with French authorities and the U.S. State Department. Dani Watt, wife of Steelers star T.J. Watt, publicly asked how sending players and families into the turmoil makes sense, while the league presses ahead with preparations unchanged.", "summary_zh": "匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。 钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。", "body_en": "NFL Sticks with France Game Amid Paris Riots.\n\nAs riots grip Paris with clashes, looting, and arrests, the NFL readies its first regular-season game there, drawing sharp questions from players' families and critics.\n\nThe Pittsburgh Steelers face the New Orleans Saints at Stade de France on October 25, despite unrest from protests over living costs, school conditions, and public services that led to thousands of arrests and injuries. NFL Commissioner Roger Goodell insists the protests are mostly peaceful and players face no danger, with ramped-up stadium security coordinated with French authorities and the U.S.\n\nState Department. Dani Watt, wife of Steelers star T.J. Watt, publicly asked how sending players and families into the turmoil makes sense, while the league presses ahead with preparations unchanged.", "body_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。\n\n匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。\n\n美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。", "url": "https://x.com/i/trending/2112984435729576320", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T19:16:37.000Z"}, {"id": "2112889351361139036", "domain": "体育", "title_en": "EA FC 27 Teases New FUT Gallery Sets for MLS, NWSL, and Saudi League", "title_zh": "EA FC 27为MLS、NWSL和沙特联赛推出全新FUT画廊套装", "hook_en": "Community accounts lit up with Halloween-themed artwork showing glowing league logos and 'NEW SETS COMING' banners, getting players hyped for fresh collectibles.", "hook_zh": "社区账户上点缀着万圣节主题的艺术品，上面显示着闪闪发光的联赛徽标和“新套装即将推出”的横幅，让玩家大肆宣传新的收藏品。", "summary_en": "Popular FUT accounts shared promotional images and in-game screenshots revealing upcoming Gallery sets for Major League Soccer, the National Women’s Soccer League, and the Roshn Saudi League. These sets let players collect and grade items from the fully licensed leagues—MLS with 30 clubs, NWSL's full women's roster, and Saudi's 18 teams—to earn custom crests, kits, Gallery Tokens, and higher levels. Players are buzzing about pack strategies, market price shifts, and how owned cards will count toward progress, seeing it as a fun way to keep rewards flowing without endless grinding.", "summary_zh": "热门FUT账号分享了宣传图片和游戏内截图，展示了美国职业足球大联盟、全国女子足球联赛和罗森沙特联赛即将推出的画廊套装。这些套装可让玩家从完全授权的联赛（拥有30个俱乐部的MLS、NWSL的完整女子名单和沙特的18支球队）中收集物品并进行评级，以获得定制徽章、套件、画廊代币和更高等级。 玩家们正在喋喋不休地讨论卡包策略、市场价格变动以及拥有的卡牌将如何计入进度，认为这是一种有趣的方式，可以在没有无休止磨练的情况下保持奖励的流畅。", "body_en": "EA FC 27 Teases New FUT Gallery Sets for MLS, NWSL, and Saudi League.\n\nCommunity accounts lit up with Halloween-themed artwork showing glowing league logos and 'NEW SETS COMING' banners, getting players hyped for fresh collectibles.\n\nPopular FUT accounts shared promotional images and in-game screenshots revealing upcoming Gallery sets for Major League Soccer, the National Women’s Soccer League, and the Roshn Saudi League.\n\nThese sets let players collect and grade items from the fully licensed leagues—MLS with 30 clubs, NWSL's full women's roster, and Saudi's 18 teams—to earn custom crests, kits, Gallery Tokens, and higher levels. Players are buzzing about pack strategies, market price shifts, and how owned cards will count toward progress, seeing it as a fun way to keep rewards flowing without endless grinding.", "body_zh": "社区账户上点缀着万圣节主题的艺术品，上面显示着闪闪发光的联赛徽标和“新套装即将推出”的横幅，让玩家大肆宣传新的收藏品。\n\n热门FUT账号分享了宣传图片和游戏内截图，展示了美国职业足球大联盟、全国女子足球联赛和罗森沙特联赛即将推出的画廊套装。\n\n这些套装可让玩家从完全授权的联赛（拥有30个俱乐部的MLS、NWSL的完整女子名单和沙特的18支球队）中收集物品并进行评级，以获得定制徽章、套件、画廊代币和更高等级。玩家们正在喋喋不休地讨论卡包策略、市场价格变动以及拥有的卡牌将如何计入进度，认为这是一种有趣的方式，可以在没有无休止磨练的情况下保持奖励的流畅。", "url": "https://x.com/i/trending/2112889351361139036", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T16:42:49.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112609504680640613", "domain": "体育", "title_en": "Columbus Crew Host St. Louis CITY SC in U.S. Open Cup Final", "title_zh": "哥伦布机员主场迎战圣路易斯城，决战美国公开杯决赛", "hook_en": "Fans in red gear packed flights from St. Louis, while Columbus supporters gear up to paint their home field black for tonight's showdown.", "hook_zh": "圣路易斯球迷身着红装挤满航班赶来，哥伦布主场球迷则准备把主场“涂黑”，迎接今夜对决。", "summary_en": "The Columbus Crew welcome St. Louis CITY SC to ScottsMiracle-Gro Field in Columbus, Ohio, for the 111th Lamar Hunt U.S. Open Cup Final at 8 p.m. ET, with the winner claiming the title and a spot in the 2027 Concacaf Champions Cup. Columbus chases their second Open Cup trophy since 2002 and aims to end a drought, while St. Louis seeks its first silverware as an MLS side and honors the city's ten past champions, the last in 1988. Both teams shared fired-up posts like “BRING IT HOME” and “IT’S OPEN CUP FINAL MATCHDAY,” as traveling St. Louis fans fill the air with passion ahead of the broadcast on Paramount+ and CBS Sports Network.", "summary_zh": "哥伦布机员将在俄亥俄州哥伦布的 ScottsMiracle-Gro Field 迎战圣路易斯城足球俱乐部，争夺第111届拉马尔·亨特美国公开杯冠军，开球时间为美东时间晚8点；胜者还将获得2027年中北美冠军杯席位。哥伦布志在拿下自2002年以来第二座公开杯，终结长期冠军荒；圣路易斯则冲击加盟美职联后的首座奖杯，并向该城此前十次夺冠、最近一次在1988年的历史致敬。双方球迷高呼“把奖杯带回家”“决赛日到了”，比赛将在 Paramount+ 与 CBS Sports Network 播出。", "body_en": "Columbus Crew Host St. Louis CITY SC in U.S. Open Cup Final.\n\nFans in red gear packed flights from St. Louis, while Columbus supporters gear up to paint their home field black for tonight's showdown.\n\nThe Columbus Crew welcome St. Louis CITY SC to ScottsMiracle-Gro Field in Columbus, Ohio, for the 111th Lamar Hunt U.S. Open Cup Final at 8 p.m. ET, with the winner claiming the title and a spot in the 2027 Concacaf Champions Cup.\n\nColumbus chases their second Open Cup trophy since 2002 and aims to end a drought, while St. Louis seeks its first silverware as an MLS side and honors the city's ten past champions, the last in 1988. Both teams shared fired-up posts like “BRING IT HOME” and “IT’S OPEN CUP FINAL MATCHDAY,” as traveling St. Louis fans fill the air with passion ahead of the broadcast on Paramount+ and CBS Sports Network.", "body_zh": "哥伦布机员主场迎战圣路易斯城，决战美国公开杯决赛。\n\n圣路易斯球迷身着红装挤满航班赶来，哥伦布主场球迷则准备把主场“涂黑”，迎接今夜对决。\n\n哥伦布机员将在俄亥俄州哥伦布的 ScottsMiracle-Gro Field 迎战圣路易斯城足球俱乐部，争夺第111届拉马尔·亨特美国公开杯冠军，开球时间为美东时间晚8点；胜者还将获得2027年中北美冠军杯席位。\n\n哥伦布志在拿下自2002年以来第二座公开杯，终结长期冠军荒；圣路易斯则冲击加盟美职联后的首座奖杯，并向该城此前十次夺冠、最近一次在1988年的历史致敬。双方球迷高呼“把奖杯带回家”“决赛日到了”，比赛将在 Paramount+ 与 CBS Sports Network 播出。", "url": "https://x.com/i/trending/2112609504680640613", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T20:51:50.000Z"}, {"id": "2112595598553608689", "domain": "体育", "title_en": "Magic Host Hawks in 2026-27 NBA Season Opener Tonight", "title_zh": "2026-27赛季NBA魔术老鹰揭幕战今晚", "hook_en": "Both teams are buzzing with energy as the Orlando Magic welcome the Atlanta Hawks to the Kia Center for the 2026-27 NBA season tip-off at 7 p.m. ET.", "hook_zh": "两支球队都充满活力，奥兰多魔术队在美国东部时间晚上7点欢迎亚特兰大老鹰队来到起亚中心参加2026-27赛季的NBA比赛。", "summary_en": "The Magic face injury hurdles with Anthony Black, Jonathan Isaac, Noah Penda, and Izaiyah Nelson ruled out, but Franz Wagner is good to go after shoulder soreness. Anthony Black stays focused despite no contract extension, calling team success more important. The Hawks miss Mouhamed Gueye and Henri Veesaar, leaning on Jalen Johnson and Nickeil Alexander-Walker, while coach Sean Sweeney makes his regular-season debut with stars Paolo Banchero and Desmond Bane leading Orlando.", "summary_zh": "魔术面部受伤的障碍， Anthony Black、Jonathan Isaac、Noah Penda和Izaiyah Nelson排除了，但Franz Wagner很适合治疗肩膀酸痛。安东尼·布莱克（ Anthony Black ）尽管没有续约，但仍然保持专注，他认为团队的成功更为重要。 老鹰队错过了Mouhamed Gueye和Henri Veesaar ，他们依靠Jalen Johnson和Nickeil Alexander-Walker ，而教练Sean Sweeney与明星Paolo Banchero和Desmond Bane领先奥兰多进行了常规赛首秀。", "body_en": "Magic Host Hawks in 2026-27 NBA Season Opener Tonight.\n\nBoth teams are buzzing with energy as the Orlando Magic welcome the Atlanta Hawks to the Kia Center for the 2026-27 NBA season tip-off at 7 p.m. ET.\n\nThe Magic face injury hurdles with Anthony Black, Jonathan Isaac, Noah Penda, and Izaiyah Nelson ruled out, but Franz Wagner is good to go after shoulder soreness.\n\nAnthony Black stays focused despite no contract extension, calling team success more important. The Hawks miss Mouhamed Gueye and Henri Veesaar, leaning on Jalen Johnson and Nickeil Alexander-Walker, while coach Sean Sweeney makes his regular-season debut with stars Paolo Banchero and Desmond Bane leading Orlando.", "body_zh": "两支球队都充满活力，奥兰多魔术队在美国东部时间晚上7点欢迎亚特兰大老鹰队来到起亚中心参加2026-27赛季的NBA比赛。\n\n魔术面部受伤的障碍， Anthony Black、Jonathan Isaac、Noah Penda和Izaiyah Nelson排除了，但Franz Wagner很适合治疗肩膀酸痛。\n\n安东尼·布莱克（ Anthony Black ）尽管没有续约，但仍然保持专注，他认为团队的成功更为重要。老鹰队错过了Mouhamed Gueye和Henri Veesaar ，他们依靠Jalen Johnson和Nickeil Alexander-Walker ，而教练Sean Sweeney与明星Paolo Banchero和Desmond Bane领先奥兰多进行了常规赛首秀。", "url": "https://x.com/i/trending/2112595598553608689", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T18:11:17.000Z"}, {"id": "2112623569473597808", "domain": "体育", "title_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash", "title_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开", "hook_en": "Picture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.", "hook_zh": "利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。", "summary_en": "On Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what. Some admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "summary_zh": "周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "body_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash.\n\nPicture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.\n\nOn Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what.\n\nSome admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "body_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开。\n\n利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。\n\n周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。\n\n也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "url": "https://x.com/i/trending/2112623569473597808", "category": "Sports", "topics": ["UEFA Champions League"], "updated_at": "2026-10-20T19:23:57.000Z"}, {"id": "2112275126901207175", "domain": "体育", "title_en": "Worlds 2026 Swiss Stage Schedule Drops with Korean-Chinese Clashes", "title_zh": "英雄联盟 S14 瑞士轮赛程出炉，开局韩中对撞", "hook_en": "Fans worldwide lit up when the first-round matchups hit, pitting Korean powerhouses against Chinese giants right from the start on October 23.", "hook_zh": "首轮对阵一公布，全球粉丝沸腾：10 月 23 日起韩华、Gen.G 等劲旅将与中国战队正面交锋。", "summary_en": "The League of Legends Worlds 2026 Swiss Stage kicks off at the Credit Union of Texas Event Center in Allen, Texas, with eight best-of-one matches including Gen.G vs. Invictus Gaming, Hanwha Life Esports vs. Top Esports, and G2 Esports vs. Dplus KIA. Start times begin at 10 a.m. PT, offering prime slots for NA and EU viewers while accommodating many global fans despite some tough hours. Former champ Crisp predicted an LPL sweep on stream, joking about Korean teams facing the 'real' challenge, as Polymarket odds give Western squads a 95% shot at knockouts and launches a $10,000 pick'ems contest.", "summary_zh": "2026 英雄联盟全球总决赛瑞士轮在得克萨斯州艾伦的 Credit Union of Texas Event Center 开战，八场 BO1 包括 Gen.G 对 Invictus Gaming、韩华生命对 Top Esports、G2 对 Dplus KIA 等。比赛自太平洋时间上午 10 点起，兼顾北美与欧洲观众。前冠军 Crisp 在直播中预测 LPL 横扫，并调侃韩队将面对「真正的考验」；Polymarket 赔率显示西方队伍晋级淘汰赛概率约 95%，同时上线 1 万美元 pick'ems 竞猜。", "body_en": "Worlds 2026 Swiss Stage Schedule Drops with Korean-Chinese Clashes.\n\nFans worldwide lit up when the first-round matchups hit, pitting Korean powerhouses against Chinese giants right from the start on October 23.\n\nThe League of Legends Worlds 2026 Swiss Stage kicks off at the Credit Union of Texas Event Center in Allen, Texas, with eight best-of-one matches including Gen.G vs. Invictus Gaming, Hanwha Life Esports vs. Top Esports, and G2 Esports vs.\n\nDplus KIA. Start times begin at 10 a.m. PT, offering prime slots for NA and EU viewers while accommodating many global fans despite some tough hours. Former champ Crisp predicted an LPL sweep on stream, joking about Korean teams facing the 'real' challenge, as Polymarket odds give Western squads a 95% shot at knockouts and launches a $10,000 pick'ems contest.", "body_zh": "英雄联盟 S14 瑞士轮赛程出炉，开局韩中对撞。\n\n首轮对阵一公布，全球粉丝沸腾：10 月 23 日起韩华、Gen.G 等劲旅将与中国战队正面交锋。\n\n2026 英雄联盟全球总决赛瑞士轮在得克萨斯州艾伦的 Credit Union of Texas Event Center 开战，八场 BO1 包括 Gen.G 对 Invictus Gaming、韩华生命对 Top Esports、G2 对 Dplus KIA 等。\n\n比赛自太平洋时间上午 10 点起，兼顾北美与欧洲观众。前冠军 Crisp 在直播中预测 LPL 横扫，并调侃韩队将面对「真正的考验」；Polymarket 赔率显示西方队伍晋级淘汰赛概率约 95%，同时上线 1 万美元 pick'ems 竞猜。", "url": "https://x.com/i/trending/2112275126901207175", "category": "Sports", "topics": ["Esports"], "updated_at": "2026-10-20T02:52:20.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起。\n\nBreiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。\n\n前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。\n\n批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。\n\n他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录。\n\n从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。\n\n印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。\n\n前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112946152933089721", "domain": "娱乐", "title_en": "CMA Tribute Special Honors Dolly Parton Tonight on ABC", "title_zh": "CMA致敬特别荣誉Dolly Parton今晚在ABC", "hook_en": "Country music lovers are gathering their tissues for an emotional night celebrating Dolly Parton's incredible life and legacy.", "hook_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。", "summary_en": "The Country Music Association airs 'CMA Presents I Will Always Love You: A Celebration of Dolly Parton' live at 9 p.m. ET on ABC and Disney+, nearly two months after her passing on August 25 at age 80 from cancer. Stars like Carrie Underwood, Reba McEntire, Kelsea Ballerini, and even Bono will perform her classics at Belmont University in Nashville, with special guests including Oprah Winfrey and Julia Roberts sharing stories. Proceeds support her Imagination Library, delivering free books to kids, making it a heartfelt nod to her music, rise from the Smoky Mountains, and philanthropy.", "summary_zh": "乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。Carrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。 收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。", "body_en": "CMA Tribute Special Honors Dolly Parton Tonight on ABC.\n\nCountry music lovers are gathering their tissues for an emotional night celebrating Dolly Parton's incredible life and legacy.\n\nThe Country Music Association airs 'CMA Presents I Will Always Love You: A Celebration of Dolly Parton' live at 9 p.m. ET on ABC and Disney+, nearly two months after her passing on August 25 at age 80 from cancer.\n\nStars like Carrie Underwood, Reba McEntire, Kelsea Ballerini, and even Bono will perform her classics at Belmont University in Nashville, with special guests including Oprah Winfrey and Julia Roberts sharing stories. Proceeds support her Imagination Library, delivering free books to kids, making it a heartfelt nod to her music, rise from the Smoky Mountains, and philanthropy.", "body_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。\n\n乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。\n\nCarrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。", "url": "https://x.com/i/trending/2112946152933089721", "category": "Entertainment", "topics": ["Music", "Country"], "updated_at": "2026-10-21T19:29:57.000Z"}, {"id": "2112630069361570032", "domain": "娱乐", "title_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories", "title_zh": "金球奖将迈克尔·杰克逊的传记片列入戏剧类", "hook_en": "Jaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.", "hook_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。", "summary_en": "Lionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "summary_zh": "Lionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。 球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "body_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories.\n\nJaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.\n\nLionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot.\n\nFans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "body_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。\n\nLionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。\n\n这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "url": "https://x.com/i/trending/2112630069361570032", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:48:00.000Z"}, {"id": "2112840787054743961", "domain": "娱乐", "title_en": "Moonlight Marks 10 Years Since Theatrical Premiere", "title_zh": "Moonlight标志着美国首次亮相和奥斯卡辉煌10周年", "hook_en": "Ten years ago today, Barry Jenkins' quiet masterpiece Moonlight arrived in theaters, capturing a young Black man's journey through identity and belonging in Miami.", "hook_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。", "summary_en": "The film follows Chiron from childhood as 'Little,' through teenage bullying, to adulthood as 'Black,' with standout performances by Mahershala Ali as a kind drug dealer and Naomie Harris as his struggling mother. It won three Oscars, including Best Picture—the first for a film with an all-Black cast and gay protagonist—and its poetic cinematography and score turn everyday moments profound. Now streaming on Netflix, with a new 4K remaster in theaters and Jenkins reflecting on its making, fans continue to praise its honest portrayal of beauty, pain, and human gray areas.", "summary_zh": "这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。 Mahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "body_en": "Ten years ago today, Barry Jenkins' Moonlight quietly arrived in U.S. theaters, forever changing conversations about identity and love through its tender gaze on a young man's life in Miami.\n\nReleased on October 21, 2016, by A24, the film follows Chiron from childhood to adulthood across three chapters, earning three Oscars including Best Picture as the first with an all-Black cast and LGBT theme. Standout performances by Mahershala Ali, Naomie Harris, Trevante Rhodes, Ashton Sanders, and Jharrel Jerome, paired with luminous cinematography and Nicholas Britell's score, turned its $1.5 million budget into $67 million worldwide and lasting praise.\n\nThis week, Netflix added it to its U.S. library while a 4K remaster returned to theaters, as fans share personal stories of its themes of vulnerability and self-acceptance.", "body_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。\n\n这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。\n\nMahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "url": "https://x.com/i/trending/2112840787054743961", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T20:52:22.000Z"}, {"id": "2112977632723607782", "domain": "娱乐", "title_en": "Netflix Adds First Three Seasons of 'From' Ahead of Halloween", "title_zh": "Netflix在万圣节前增加了“From”的前三季", "hook_en": "Strangers trapped in a town they can't escape, with monsters lurking every night—that's the grip of 'From,' now streaming on Netflix for a new crowd.", "hook_zh": "陌生人被困在一个他们无法逃脱的小镇上，每天晚上都有怪物潜伏在这里--这就是《From》的魅力所在，现在Netflix上正在为新的观众提供流媒体服务。", "summary_en": "Netflix brought seasons one through three of the sci-fi horror series 'From' to its U.S. library on October 19, letting viewers dive into the mystery of a inescapable town and its nightly terrors. Harold Perrineau plays Boyd Stevens, the leader keeping the community together amid the chaos. Fans are thrilled for newcomers to join, sharing stories of past binge struggles, though season four stays on MGM+ and the final season arrives there in 2027. The timing fits perfectly with Halloween, drawing fresh enthusiasm for the slow-burn puzzle that premiered in 2022.", "summary_zh": "10月19日， Netflix将科幻恐怖系列“From”的第一季至第三季带到了其美国图书馆，让观众深入了解一个不可避免的小镇的奥秘及其夜间恐怖。Harold Perrineau扮演博伊德·史蒂文斯（ Boyd Stevens ） ，在混乱中保持社区团结的领导者。粉丝们很高兴新人加入，分享过去狂欢挣扎的故事，尽管第四季在MGM +上停留，最后一季将在2027年到达那里。 这个时机与万圣节完美契合，为2022年首次亮相的慢火拼图带来了新的热情。", "body_en": "Netflix Adds First Three Seasons of 'From' Ahead of Halloween.\n\nStrangers trapped in a town they can't escape, with monsters lurking every night—that's the grip of 'From,' now streaming on Netflix for a new crowd.\n\nNetflix brought seasons one through three of the sci-fi horror series 'From' to its U.S. library on October 19, letting viewers dive into the mystery of a inescapable town and its nightly terrors.\n\nHarold Perrineau plays Boyd Stevens, the leader keeping the community together amid the chaos. Fans are thrilled for newcomers to join, sharing stories of past binge struggles, though season four stays on MGM+ and the final season arrives there in 2027. The timing fits perfectly with Halloween, drawing fresh enthusiasm for the slow-burn puzzle that premiered in 2022.", "body_zh": "陌生人被困在一个他们无法逃脱的小镇上，每天晚上都有怪物潜伏在这里--这就是《From》的魅力所在，现在Netflix上正在为新的观众提供流媒体服务。\n\n10月19日， Netflix将科幻恐怖系列“From”的第一季至第三季带到了其美国图书馆，让观众深入了解一个不可避免的小镇的奥秘及其夜间恐怖。Harold Perrineau扮演博伊德·史蒂文斯（ Boyd Stevens ） ，在混乱中保持社区团结的领导者。\n\n粉丝们很高兴新人加入，分享过去狂欢挣扎的故事，尽管第四季在MGM +上停留，最后一季将在2027年到达那里。这个时机与万圣节完美契合，为2022年首次亮相的慢火拼图带来了新的热情。", "url": "https://x.com/i/trending/2112977632723607782", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T18:51:48.000Z"}, {"id": "2112352804241285515", "domain": "娱乐", "title_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music", "title_zh": "德维恩·约翰逊（ Dwayne Johnson ）变身为蜥蜴音乐的老鸡人", "hook_en": "Dwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.", "hook_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。", "summary_en": "Johnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV. Set photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "summary_zh": "约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "body_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music.\n\nDwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.\n\nJohnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV.\n\nSet photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "body_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。\n\n约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:07:08.000Z"}, {"id": "2112278399108710855", "domain": "娱乐", "title_en": "Robert Pattinson’s 'Primetime' Hits Digital November 3 After Quick Theatrical Run", "title_zh": "帕丁森新片《Primetime》院线短暂上映后11月3日登陆数字平台", "hook_en": "Robert Pattinson steps into the shoes of 'To Catch a Predator' host Chris Hansen in A24's tense thriller, racing from theaters to your screen in just weeks.", "hook_zh": "罗伯特·帕丁森在A24惊悚片中饰演《钓鱼执法》主持人克里斯·汉森，影片上映数周后即将登陆数字端。", "summary_en": "Directed by Lance Oppenheim, 'Primetime' dramatizes the 2006 origins of NBC's Dateline sting operations and their ethical dilemmas, with Pattinson leading alongside Merritt Wever, Skyler Gisondo, and Phoebe Bridgers. It premiered at Venice, launched in U.S. theaters on September 25, and arrives on digital platforms November 3—about six weeks later—for wider access. Sony Pictures recently acquired international rights for theatrical releases in markets like Germany, Latin America, South Korea, and Southeast Asia, boosting its awards-season buzz. Fans expressed excitement over the expanded reach, though some noted shorter windows and the film's sensitive topic.", "summary_zh": "由兰斯·奥本海姆执导的《Primetime》再现2006年NBC《日界线》钓鱼执法行动的起源及其伦理争议，帕丁森领衔，梅里特·韦弗、斯凯勒·吉松多、菲比·布里杰斯等出演。影片威尼斯首映，9月25日登陆美国院线，约六周后于11月3日登陆数字平台扩大受众。索尼影业近期拿下国际发行权，将在德国、拉美、韩国与东南亚等地院线上映，奖季热度随之升温。粉丝对扩大发行表示兴奋，也有人注意到窗口期缩短以及题材敏感。", "body_en": "Robert Pattinson’s 'Primetime' Hits Digital November 3 After Quick Theatrical Run.\n\nRobert Pattinson steps into the shoes of 'To Catch a Predator' host Chris Hansen in A24's tense thriller, racing from theaters to your screen in just weeks.\n\nDirected by Lance Oppenheim, 'Primetime' dramatizes the 2006 origins of NBC's Dateline sting operations and their ethical dilemmas, with Pattinson leading alongside Merritt Wever, Skyler Gisondo, and Phoebe Bridgers. It premiered at Venice, launched in U.S.\n\ntheaters on September 25, and arrives on digital platforms November 3—about six weeks later—for wider access. Sony Pictures recently acquired international rights for theatrical releases in markets like Germany, Latin America, South Korea, and Southeast Asia, boosting its awards-season buzz. Fans expressed excitement over the expanded reach, though some noted shorter windows and the film's sensitive topic.", "body_zh": "帕丁森新片《Primetime》院线短暂上映后11月3日登陆数字平台。\n\n罗伯特·帕丁森在A24惊悚片中饰演《钓鱼执法》主持人克里斯·汉森，影片上映数周后即将登陆数字端。\n\n由兰斯·奥本海姆执导的《Primetime》再现2006年NBC《日界线》钓鱼执法行动的起源及其伦理争议，帕丁森领衔，梅里特·韦弗、斯凯勒·吉松多、菲比·布里杰斯等出演。影片威尼斯首映，9月25日登陆美国院线，约六周后于11月3日登陆数字平台扩大受众。\n\n索尼影业近期拿下国际发行权，将在德国、拉美、韩国与东南亚等地院线上映，奖季热度随之升温。粉丝对扩大发行表示兴奋，也有人注意到窗口期缩短以及题材敏感。", "url": "https://x.com/i/trending/2112278399108710855", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T02:13:26.000Z"}, {"id": "2112961308597338219", "domain": "娱乐", "title_en": "Kid Cudi to Write, Direct and Star as Jean-Michel Basquiat in 'JEAN'", "title_zh": "Kid Cudi将在Jean-Michel Basquiat传记片中撰写、导演和主演", "hook_en": "Kid Cudi slipped into a sharp suit and wild wig, posing against graffiti walls to channel Jean-Michel Basquiat's iconic vibe. It's the first glimpse of his passion project come to life.", "hook_zh": "多年来，其他人一直把他称为让-米歇尔·巴斯奎特（ Jean-Michel Basquiat ） ，库迪小子抓住了笔。现在，他正在按照自己的方式拍摄《吉恩》，拍摄时间定在2027年。", "summary_en": "The rapper-actor announced he'll write, direct and star as the legendary artist in the upcoming film 'JEAN,' with filming starting in 2027. After years of fan requests and stalled ideas, Cudi took matters into his own hands, sharing wardrobe test photos and a script page dated August 2026. He poured extensive research into the script, calling it a love letter to Basquiat, 1980s New York and dreamers everywhere. Fans have lit up with excitement over the parallels between Cudi's and Basquiat's creative journeys.", "summary_zh": "这位音乐家解释说，他负责是因为没有其他人跟进： “今年，我终于说他妈的， ima自己写的。“宣传图片显示， Cudi穿着量身定制的西装，演绎巴斯奎特的戏剧风格，赢得了粉丝们的赞誉，他们从共同的创意之旅中看到了自然契合。 库迪称这部电影是20世纪80年代纽约巴斯奎特的情书，借鉴了他在“Doe”等项目中的导演经验。“虽然有些人想知道在1996年的电影后如何捕捉巴斯奎特的精髓，但许多人对这种个人摄影表示欢迎。", "body_en": "Kid Cudi to Write, Direct and Star in Jean-Michel Basquiat Biopic.\n\nKid Cudi grabbed the pen after years of others pitching him as Jean-Michel Basquiat. Now he's making 'JEAN' his own way, with filming set for 2027.\n\nThe musician explained he took charge because no one else followed through: 'This year, I finally said f*ck it, ima write it myself.' Promotional images show Cudi channeling Basquiat's dramatic style in tailored suits, earning praise from fans who see a natural fit from their shared creative journeys.\n\nCudi calls the film a love letter to Basquiat, 1980s New York, building on his directing experience with projects like 'Doe.' While some wonder about capturing Basquiat's essence after the 1996 film, many welcome this personal take.", "body_zh": "多年来，其他人一直把他称为让-米歇尔·巴斯奎特（ Jean-Michel Basquiat ） ，库迪小子抓住了笔。现在，他正在按照自己的方式拍摄《吉恩》，拍摄时间定在2027年。\n\n这位音乐家解释说，他负责是因为没有其他人跟进： “今年，我终于说他妈的， ima自己写的。“宣传图片显示， Cudi穿着量身定制的西装，演绎巴斯奎特的戏剧风格，赢得了粉丝们的赞誉，他们从共同的创意之旅中看到了自然契合。\n\n库迪称这部电影是20世纪80年代纽约巴斯奎特的情书，借鉴了他在“Doe”等项目中的导演经验。“虽然有些人想知道在1996年的电影后如何捕捉巴斯奎特的精髓，但许多人对这种个人摄影表示欢迎。", "url": "https://x.com/i/trending/2112961308597338219", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T20:11:12.000Z"}, {"id": "2112918023249989711", "domain": "娱乐", "title_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'", "title_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程", "hook_en": "Sunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.", "hook_zh": "Sunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。", "summary_en": "The 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in. She first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "summary_zh": "这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "body_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'.\n\nSunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.\n\nThe 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in.\n\nShe first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "body_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程。\n\nSunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。\n\n这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。\n\n她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "url": "https://x.com/i/trending/2112918023249989711", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T14:50:09.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动。\n\n邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。\n\n10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。\n\n粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照。\n\nPooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。\n\n粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2112588455616397480", "domain": "娱乐", "title_en": "The Diplomat Season 4 Delivers Tense Diplomacy and Shocking Finale", "title_zh": "《外交官》第四季上线，结局获赞收视强劲", "hook_en": "Keri Russell's Ambassador Kate Wyler publicly resigns at the G7 summit, joined by her husband Hal, in a bold stand for country over party that left fans stunned.", "hook_zh": "凯丽·拉塞尔饰演的大使凯特·怀勒在正装对峙与个人代价中前行，结局在职责与分裂忠诚间权衡。", "summary_en": "Season 4 of Netflix's political thriller launched October 15 with eight episodes of high-stakes U.S.-UK diplomacy, marital strains, and power plays amid fallout from a secret Russian nuclear crisis. Jodie Whittaker joins as the new British Prime Minister Bethan Vaughn, adding alliance and friction to Kate's world, while the cast including Rufus Sewell and Allison Janney shines with standout chemistry. Debuting with 4.8 million views in its first week across 58 countries, the season matches prior success and builds to mass resignations that highlight moral fractures, fueling fan calls for Season 5.", "summary_zh": "Netflix 于 10 月 15 日上线《外交官》第四季全部八集，首周 480 万次观看，进入 58 国榜单前十。斯蒂芬·金称赞结局关于「国家高于党派」的讯息；粉丝催更第五季并盛赞拉塞尔演技。卡斯还包括拉弗斯·休厄尔与艾莉森·珍妮等，剧组获 AAM 奖项肯定。", "body_en": "The Diplomat Season 4 Delivers Tense Diplomacy and Shocking Finale.\n\nKeri Russell's Ambassador Kate Wyler publicly resigns at the G7 summit, joined by her husband Hal, in a bold stand for country over party that left fans stunned.\n\nSeason 4 of Netflix's political thriller launched October 15 with eight episodes of high-stakes U.S.-UK diplomacy, marital strains, and power plays amid fallout from a secret Russian nuclear crisis.\n\nJodie Whittaker joins as the new British Prime Minister Bethan Vaughn, adding alliance and friction to Kate's world, while the cast including Rufus Sewell and Allison Janney shines with standout chemistry. Debuting with 4.8 million views in its first week across 58 countries, the season matches prior success and builds to mass resignations that highlight moral fractures, fueling fan calls for Season 5.", "body_zh": "《外交官》第四季上线，结局获赞收视强劲。\n\n凯丽·拉塞尔饰演的大使凯特·怀勒在正装对峙与个人代价中前行，结局在职责与分裂忠诚间权衡。\n\nNetflix 于 10 月 15 日上线《外交官》第四季全部八集，首周 480 万次观看，进入 58 国榜单前十。\n\n斯蒂芬·金称赞结局关于「国家高于党派」的讯息；粉丝催更第五季并盛赞拉塞尔演技。卡斯还包括拉弗斯·休厄尔与艾莉森·珍妮等，剧组获 AAM 奖项肯定。", "url": "https://x.com/i/trending/2112588455616397480", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T20:39:46.000Z"}, {"id": "2112867591127793782", "domain": "娱乐", "title_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes", "title_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日", "hook_en": "Glen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.", "hook_zh": "Glen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。", "summary_en": "Born October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters. Entertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "summary_zh": "Powell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。Pop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "body_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes.\n\nGlen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.\n\nBorn October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters.\n\nEntertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "body_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日。\n\nGlen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。\n\nPowell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。\n\nPop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "url": "https://x.com/i/trending/2112867591127793782", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T11:29:11.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Limit Unavoidable, But Overshoot Can Be Limited", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The UN has delivered sobering news: the world will exceed the Paris Agreement's 1.5°C warming threshold. The focus now shifts to capping the rise and pulling temperatures back by century's end.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "A new UN Environment Programme report declares it impossible to stay below 1.5°C without overshoot, ahead of COP31 talks in Turkey. Current policies point to up to 2.8°C warming this century, while full national pledges would limit it to 2.6°C—worse than last year's outlook due to U.S. emissions rises and data revisions. To cap peak warming at 1.7–1.8°C mid-century with a fair shot at returning to 1.5°C by 2100, emissions must drop 18 percent by 2030 and 45 percent by 2035 from 2025 levels, plus massive carbon removal. UN leaders like António Guterres and Inger Andersen call for urgent cuts in coal, methane, and faster clean energy growth to avoid locking in worse impacts.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T19:30:19.000Z"}, {"id": "2112769667550888269", "domain": "科学", "title_en": "APA Faces Accreditation Scrutiny Over Activism in Psychology Conferences", "title_zh": "美国心理学会因会议政治化面临认证审查", "hook_en": "Psychologists gathered in New York for a major conference, but the panels leaned heavily into political themes like abolishing the family and queer anarchist psychoanalysis, with no conservative voices in sight.", "hook_zh": "心理学家齐聚纽约参加重要会议，但议程大量偏向「废除家庭」「酷儿无政府精神分析」等政治主题，几乎不见保守派声音。", "summary_en": "A Wall Street Journal opinion piece by Colin Wright and Andrew Hartz highlights criticism of the American Psychological Association for blending activism with science, spotlighting Division 39's recent conference where about 70 of 90 panels pushed left-wing topics and sessions like 'Feel the F— Fantasy' offered continuing education credits. A bipartisan board voted 7-4 last month to recommend suspending the APA's federal accreditation authority, amid concerns over antisemitism allegations and elected president Candice Hargons' focus on 'systemic intersectional oppression.' Similar issues appear at the American Academy of Child and Adolescent Psychiatry, which declined to discuss evidence on childhood gender transitions. Critics argue this erodes public trust in evidence-based care for vulnerable patients.", "summary_zh": "科林·赖特与安德鲁·哈茨在《华尔街日报》评论中批评美国心理学会把行动主义与科学混为一谈，点名第 39 分会近期会议约 90 场专题中约 70 场偏向左翼议题，且如「Feel the F— Fantasy」等场次仍可获继续教育学分。两党组成的委员会上月以 7 比 4 建议暂停该协会的联邦认证授权，背景还包括反犹指控争议，以及当选会长 Candice Hargons 聚焦「系统性交叉压迫」的取向。美国儿童与青少年精神病学学会也出现类似问题，并拒绝讨论童年性别过渡相关证据。批评者认为，这侵蚀公众对面向脆弱患者的循证照护的信任。", "body_en": "APA Faces Accreditation Scrutiny Over Activism in Psychology Conferences.\n\nPsychologists gathered in New York for a major conference, but the panels leaned heavily into political themes like abolishing the family and queer anarchist psychoanalysis, with no conservative voices in sight.\n\nA Wall Street Journal opinion piece by Colin Wright and Andrew Hartz highlights criticism of the American Psychological Association for blending activism with science, spotlighting Division 39's recent conference where about 70 of 90 panels pushed left-wing topics and sessions like 'Feel the F— Fantasy' offered continuing education credits.\n\nA bipartisan board voted 7-4 last month to recommend suspending the APA's federal accreditation authority, amid concerns over antisemitism allegations and elected president Candice Hargons' focus on 'systemic intersectional oppression.' Similar issues appear at the American Academy of Child and Adolescent Psychiatry, which declined to discuss evidence on childhood gender transitions. Critics argue this erodes public trust in evidence-based care for vulnerable patients.", "body_zh": "美国心理学会因会议政治化面临认证审查。\n\n心理学家齐聚纽约参加重要会议，但议程大量偏向「废除家庭」「酷儿无政府精神分析」等政治主题，几乎不见保守派声音。\n\n科林·赖特与安德鲁·哈茨在《华尔街日报》评论中批评美国心理学会把行动主义与科学混为一谈，点名第 39 分会近期会议约 90 场专题中约 70 场偏向左翼议题，且如「Feel the F— Fantasy」等场次仍可获继续教育学分。两党组成的委员会上月以 7 比 4 建议暂停该协会的联邦认证授权，背景还包括反犹指控争议，以及当选会长 Candice Hargons 聚焦「系统性交叉压迫」的取向。\n\n美国儿童与青少年精神病学学会也出现类似问题，并拒绝讨论童年性别过渡相关证据。批评者认为，这侵蚀公众对面向脆弱患者的循证照护的信任。", "url": "https://x.com/i/trending/2112769667550888269", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T14:50:00.000Z"}, {"id": "2112946155130904714", "domain": "科学", "title_en": "Coherence Neuro Raises $45M for Adaptive Brain Cancer Implant", "title_zh": "Coherence Neuro为适应性脑癌植入物筹集了4500万美元$", "hook_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'", "hook_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”", "summary_en": "The San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable. It builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "summary_zh": "这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。 它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "body_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'\n\nThe San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable.\n\nIt builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "body_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”\n\n这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。\n\n它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "url": "https://x.com/i/trending/2112946155130904714", "category": "News", "topics": ["Business & Finance", "Technology", "Biotech"], "updated_at": "2026-10-21T19:57:20.000Z"}, {"id": "2112968032066920582", "domain": "科学", "title_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted", "title_zh": "回顾生物圈 2 号氧气危机与混乱任务", "hook_en": "Eight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.", "hook_zh": "八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。", "summary_en": "Biosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk. Pigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "summary_zh": "造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "body_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted.\n\nEight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.\n\nBiosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk.\n\nPigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "body_zh": "回顾生物圈 2 号氧气危机与混乱任务。\n\n八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。\n\n造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。\n\n猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "url": "https://x.com/i/trending/2112968032066920582", "category": "News", "topics": ["News", "Science"], "updated_at": "2026-10-21T18:10:40.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州模拟轨道阳光", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州模拟轨道阳光。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\n10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。\n\n演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112820742060495085", "domain": "科学", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z"}, {"id": "2112908301625356787", "domain": "科学", "title_en": "AI Agents Analyze Brain Data in 32 Minutes for Neurodegenerative Clues", "title_zh": "AI 智能体 32 分钟挖出脑疾病新线索", "hook_en": "What once took human researchers months, thousands of AI agents accomplished in just 32 minutes, uncovering fresh leads on diseases like Parkinson's.", "hook_zh": "成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。", "summary_en": "OpenAI teamed up with PerturbAI and Scripps Research to apply distributed biological reasoning to a massive CRISPR atlas of millions of mouse brain cells from nearly 2,000 gene disruptions. Around 1,946 AI agents each tackled one perturbation, scanned scientific literature, and generated reports that formed a comprehensive reasoning atlas, citing over 700 papers compared to just 11 from a single agent. Standout findings included links between DCTN1 disruption and cholesterol transport issues in Perry syndrome, plus differences in TSC1 and TSC2 effects on neuronal genes. Blinded experts favored the multi-agent outputs 75% of the time, and the teams plan to expand the work while stressing these are hypotheses needing lab validation.", "summary_zh": "OpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "body_en": "AI Agents Analyze Brain Data in 32 Minutes for Neurodegenerative Clues.\n\nWhat once took human researchers months, thousands of AI agents accomplished in just 32 minutes, uncovering fresh leads on diseases like Parkinson's.\n\nOpenAI teamed up with PerturbAI and Scripps Research to apply distributed biological reasoning to a massive CRISPR atlas of millions of mouse brain cells from nearly 2,000 gene disruptions. Around 1,946 AI agents each tackled one perturbation, scanned scientific literature, and generated reports that formed a comprehensive reasoning atlas, citing over 700 papers compared to just 11 from a single agent.\n\nStandout findings included links between DCTN1 disruption and cholesterol transport issues in Perry syndrome, plus differences in TSC1 and TSC2 effects on neuronal genes. Blinded experts favored the multi-agent outputs 75% of the time, and the teams plan to expand the work while stressing these are hypotheses needing lab validation.", "body_zh": "AI 智能体 32 分钟挖出脑疾病新线索。\n\n成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。\n\nOpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。\n\n亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "url": "https://x.com/i/trending/2112908301625356787", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:16:54.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112331788529840225", "domain": "科学", "title_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide", "title_zh": "特朗普削减气象卫星计划，引发专家分歧", "hook_en": "Experts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.", "hook_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。", "summary_en": "The Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion. A Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "summary_zh": "特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。 包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "body_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide.\n\nExperts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.\n\nThe Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion.\n\nA Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "body_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。\n\n特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。\n\n政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "url": "https://x.com/i/trending/2112331788529840225", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:06:32.000Z"}, {"id": "2112453611825377473", "domain": "科学", "title_en": "Japan Launches MMX Spacecraft for First Phobos Sample Return", "title_zh": "日本发射MMX航天器实现首次火卫一样品返回", "hook_en": "Mission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.", "hook_zh": "随着MMX探测器与火箭分离，日本的任务控制器欢呼雀跃，开始了长达十年的从火星马铃薯形状的卫星火卫一中获取样品的探索。", "summary_en": "Japan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031. The mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "summary_zh": "日本无人MMX航天器周二从种子岛航天中心乘坐H3火箭升空，开始为期10个月的火星之旅，研究火卫一，并在2031年之前返回至少10克的表面材料。该任务将从2027年开始绕火星运行，在2029年左右部署来自法国和德国的火星车，并尝试多达两次着陆，美国宇航局将提供P-Sampler等关键仪器用于快速采样。 科学家的目标是了解火卫一是被捕获的小行星还是撞击碎片，从而揭示太阳系的起源和未来的火星探索。", "body_en": "Mission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.\n\nJapan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031.\n\nThe mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "body_zh": "随着MMX探测器与火箭分离，日本的任务控制器欢呼雀跃，开始了长达十年的从火星马铃薯形状的卫星火卫一中获取样品的探索。\n\n日本无人MMX航天器周二从种子岛航天中心乘坐H3火箭升空，开始为期10个月的火星之旅，研究火卫一，并在2031年之前返回至少10克的表面材料。\n\n该任务将从2027年开始绕火星运行，在2029年左右部署来自法国和德国的火星车，并尝试多达两次着陆，美国宇航局将提供P-Sampler等关键仪器用于快速采样。科学家的目标是了解火卫一是被捕获的小行星还是撞击碎片，从而揭示太阳系的起源和未来的火星探索。", "url": "https://x.com/i/trending/2112453611825377473", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T02:12:34.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112826878222610489", "domain": "科学", "title_en": "Biosphere 2's 1991 Experiment Relived Through Viral Account", "title_zh": "Biosphere 2 1991年通过病毒账户重现的实验", "hook_en": "Eight people sealed themselves in a massive glass dome in the Arizona desert, aiming to live off their own farm for two years. Two years in, just a handful of goats kept them reliably fed.", "hook_zh": "八人在亚利桑那州沙漠中的一个巨大的玻璃穹顶中将自己封闭起来，目标是靠自己的农场生活两年。两年后，只有少数山羊能够可靠地喂养它们。", "summary_en": "The $150 million Biosphere 2 project created a sealed world with rainforest, ocean, and farmland to test human self-sufficiency. Crew grew 80 percent of their calories from crops like sweet potatoes and bananas, supplemented by goats' milk, chickens' eggs, and pigs, but oxygen plunged to high-altitude levels from hungry soil microbes, forcing outside help. They lost 15-25 pounds each adapting to a lean diet that boosted some health markers, completing the mission with key lessons on closed ecosystems now studied at the University of Arizona.", "summary_zh": "耗资1.5亿美元的Biosphere 2项目创造了一个拥有热带雨林、海洋和农田的封闭世界，以测试人类的自给自足能力。船员80%的卡路里来自红薯和香蕉等作物，再加上山羊奶、鸡蛋和猪，但氧气从饥饿的土壤微生物中骤降到高海拔水平，迫使外界提供帮助。 他们每人减掉15-25磅，以适应瘦肉饮食，这增加了一些健康指标，完成了现在在亚利桑那大学学习的关于封闭生态系统的关键课程的使命。", "body_en": "Eight people sealed themselves in a massive glass dome in the Arizona desert, aiming to live off their own farm for two years. Two years in, just a handful of goats kept them reliably fed.\n\nThe $150 million Biosphere 2 project created a sealed world with rainforest, ocean, and farmland to test human self-sufficiency.\n\nCrew grew 80 percent of their calories from crops like sweet potatoes and bananas, supplemented by goats' milk, chickens' eggs, and pigs, but oxygen plunged to high-altitude levels from hungry soil microbes, forcing outside help. They lost 15-25 pounds each adapting to a lean diet that boosted some health markers, completing the mission with key lessons on closed ecosystems now studied at the University of Arizona.", "body_zh": "八人在亚利桑那州沙漠中的一个巨大的玻璃穹顶中将自己封闭起来，目标是靠自己的农场生活两年。两年后，只有少数山羊能够可靠地喂养它们。\n\n耗资1.5亿美元的Biosphere 2项目创造了一个拥有热带雨林、海洋和农田的封闭世界，以测试人类的自给自足能力。\n\n船员80%的卡路里来自红薯和香蕉等作物，再加上山羊奶、鸡蛋和猪，但氧气从饥饿的土壤微生物中骤降到高海拔水平，迫使外界提供帮助。他们每人减掉15-25磅，以适应瘦肉饮食，这增加了一些健康指标，完成了现在在亚利桑那大学学习的关于封闭生态系统的关键课程的使命。", "url": "https://x.com/i/trending/2112826878222610489", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T08:48:08.000Z"}]};
